insert into public.learning_lessons(id,section_id,title,theory,video_url,cards,steps,sort_order,published,archived,ever_published) values
('ed95281f-5a39-5f27-94ca-af9314338e39','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','Задача дилера и цель игры','После этого блока вы сможете объяснить, как устроена раздача в безлимитном Техасском холдеме, определить позиции и очередность действий, отличить большой блайнд от анте и назвать задачи дилера.

1. Дилер и игрок: разные задачи

Игрок старается выиграть банк. Дилер не играет за участников: он ведёт раздачу нейтрально, следит за очередностью действий, картами, ставками и правильной передачей банка. Дилер не советует, какие карты разыгрывать и какое действие выгоднее.

Если возникает спор, дилер останавливает развитие спорной ситуации, сохраняет карты и фишки так, чтобы можно было восстановить события, и вызывает флора. Флор — сотрудник, уполномоченный принимать решения по регламенту турнира. Дилер кратко сообщает факты, не поддерживая одну из сторон.

2. Что такое банк и как выиграть раздачу

Банк — фишки, внесённые в раздачу: обязательные взносы и ставки игроков. Стек — фишки, оставшиеся у конкретного игрока. Живая рука — карты участника, который ещё не сбросил их и не лишился права продолжать раздачу по решению, принятому согласно регламенту.

У каждого игрока две закрытые карманные карты. В течение раздачи на стол могут выйти пять общих карт — борд. Итоговая комбинация всегда состоит из пяти карт: можно использовать обе карманные карты, одну или ни одной, если лучшая комбинация полностью находится на борде.

Выиграть можно двумя способами:
• Остаться единственным игроком с живыми картами, когда все соперники сбросили карты. Открывать весь борд для этого не требуется.
• На вскрытии показать лучшую пятикарточную комбинацию среди игроков, претендующих на соответствующий банк. При равенстве лучших комбинаций банк делится по правилам турнира.

Подробное сравнение комбинаций разбирается в отдельном разделе «Комбинации».',NULL,'[]'::jsonb,'[]'::jsonb,0,true,false,true),
('6bf5259d-00c2-53e4-a8a6-7da665f6b583','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','Позиции, блайнды и анте','3. Баттон, позиции и блайнды

Баттон (BTN) — жетон, обозначающий позицию условного сдающего. За клубным столом карты раздаёт дилер, а баттон нужен для определения позиций и порядка действий.

При трёх и более игроках за столом слева от баттона по часовой стрелке находятся малый блайнд (SB), затем большой блайнд (BB). Блайнды — обязательные ставки до раздачи карт. Их размер задаётся структурой турнира. Например, при уровне 100/200 малый блайнд составляет 100, большой — 200.

UTG — игрок, действующий первым на префлопе после большого блайнда. CO, или катофф, — позиция непосредственно перед баттоном. Для дилера важнее не название позиции само по себе, а понимание, у кого сейчас очередь.

Пока никто не выбыл и состав стола не меняется, баттон после раздачи переходит на следующее занятое место по часовой стрелке. При выбывании игроков применяется процедура мёртвого баттона; в хедз-апе действует отдельная расстановка.

4. Анте: правило нашего клуба

Анте — обязательный взнос в банк до раздачи карт. В нашем клубе используется анте большого блайнда: его платит только игрок на позиции BB, размер анте — один большой блайнд.

Пример при достаточном стеке и уровне 100/200:
• Малый блайнд вносит 100.
• Большой блайнд вносит 200 как блайнд и ещё 200 как анте. Всего с него — 400.
• До добровольных действий игроков в банке уже 500.

Анте отделяется от ставки BB и забирается в банк. Оно не увеличивает сумму, которую остальные должны уравнять: игрок без ранее внесённой ставки платит 200 для колла BB, а не 400. Большой блайнд не ставит «двойной блайнд» — это два разных взноса.

Зачем анте? Оно увеличивает начальный банк и делает борьбу за него более значимой, поддерживая динамику игры. Анте идёт в банк раздачи, а не является комиссией клуба или казино.

При недостаточном стеке в СПЛ сначала оплачивается анте, затем большой блайнд. Например, при уровне 100/200 и анте 200 у игрока на BB осталось 250: 200 уходят в анте, оставшиеся 50 — в большой блайнд. Анте не становится частью живой ставки BB. Неполный взнос BB не уменьшает установленную сумму колла для остальных. Если остатка не хватает на полные обязательные взносы, сохраните анте и живую часть BB различимыми. Перед формированием и передачей банков обратитесь к флору за решением о праве короткого игрока на соответствующие суммы; не определяйте это право только по порядку списания фишек.

При игре вдвоём за столом — в хедз-апе — анте в нашем клубе не взимается. При уровне 100/200 BTN/SB ставит 100, BB — 200; до добровольных действий в банке 300.',NULL,'[]'::jsonb,'[]'::jsonb,1,true,false,true),
('b6004bcc-7958-5fa6-b4a1-448e9c4a7dec','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','Улицы, очередность и вскрытие','5. Четыре улицы: префлоп, флоп, тёрн и ривер

Префлоп. Игроки получают по две карманные карты; общих карт пока нет. При трёх и более игроках за столом первым действует игрок слева от BB, дальше — по часовой стрелке. Блайнды входят в ставки этой улицы. Если до BB дошли только коллы, у него всё ещё есть право на действие: чек или допустимый рейз. Уравнивание блайнда остальными само по себе не закрывает торги.

Флоп. После завершения префлопа дилер сжигает верхнюю карту закрыто и открывает три общие карты. Сжигание, или бёрн, — отдельная процедура: сожжённая карта не является частью борда. На флопе первым действует ближайший слева от баттона игрок с живыми картами и фишками для действия. Это не обязательно SB: он мог сбросить карты, выбыть или находиться в олл-ине.

Тёрн. После завершения торгов на флопе дилер сжигает одну карту и открывает четвёртую общую. Порядок действий такой же, как на флопе.

Ривер. После завершения торгов на тёрне дилер сжигает одну карту и открывает пятую общую. Затем проводится последний круг торгов, если ещё возможны ставки.

Круг торгов завершён, когда все игроки, которым положено действовать, сделали необходимые действия и все остающиеся в игре ставки уравнены, кроме неполных вкладов игроков в олл-ине. Один колл не означает автоматического перехода на следующую улицу.

Если все, кроме одного, сбросили карты, раздача заканчивается без дальнейшего открытия борда. Если ставки больше невозможны из-за олл-инов, повторно предлагать таким игрокам действие не нужно; дальше применяется процедура вскрытия и открытия оставшегося борда.

6. Вскрытие и передача банка

Шоудаун — вскрытие оставшихся рук для определения победителя. Победителя определяют карты, а не название комбинации, произнесённое игроком. Для корректного предъявления руки открывают обе карманные карты так, чтобы их можно было прочитать.

В стандартной турнирной процедуре без олл-ина, если на ривере была ставка или рейз, первым показывает последний агрессор этой улицы. Если на ривере все сыграли чек, первым показывает ближайший слева от баттона игрок с живой рукой. Это не означает, что последний агрессор любой более ранней улицы автоматически открывается первым.

Когда игрок находится в олл-ине и дальнейшие ставки всех оставшихся участников завершены, применяется обязательное вскрытие всех живых рук без ожидания ривера. Наличие одного олл-ина само по себе ещё не завершает торги между игроками с оставшимися фишками.

Дилер проверяет комбинации и право на каждый банк, объявляет результат и только затем передаёт фишки. Нельзя отдавать банк только потому, что участник уверенно назвал свою руку. Спор по вскрытию, сброшенным картам или праву на банк разбирается с флором.',NULL,'[]'::jsonb,'[]'::jsonb,2,true,false,true),
('85bc83b1-8550-56de-90f2-38e35b3f01fc','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','Хедз-ап и мёртвый баттон','7. Хедз-ап: когда за столом остаются двое

Важно различать два случая: за столом осталось два участника турнира либо в конкретной раздаче из большого стола продолжили играть двое. Перестановка позиций нужна только в первом случае — не после каждого фолда остальных игроков.

При игре вдвоём BTN одновременно является SB; второй игрок — BB. На префлопе первым действует BTN/SB. На флопе, тёрне и ривере первым действует BB, если у него есть фишки для действия. Первая карманная карта при раздаче идёт BB.

При переходе к игре вдвоём позиции выставляют так, чтобы один игрок не получил BB две раздачи подряд из-за перехода; баттон заново случайным образом не разыгрывают. В нашем клубе в хедз-апе анте не взимается. Это правило относится к игре двух участников за столом, а не к раздаче большого стола, в которой остальные игроки уже сбросили карты.

8. Зачем нужен мёртвый баттон

Представим четыре соседних места: на месте 1 — BTN, на месте 2 — SB, на месте 3 — BB, на месте 4 — следующий игрок. После раздачи игрок с места 2 выбывает.

При процедуре мёртвого баттона в следующей раздаче BB переходит на место 4, SB оказывается на месте 3, а BTN — на пустом месте 2. Такой BTN называют мёртвым. Пустому месту карты не раздают.

Смысл процедуры — сохранить правильную очередность обязательных ставок, а не просто каждый раз ставить баттон перед следующим живым игроком. Пример относится к столу с тремя и более оставшимися игроками; пересадки, несколько пустых мест и переход в хедз-ап разбираются отдельно.',NULL,'[]'::jsonb,'[]'::jsonb,3,true,false,true),
('f4cf90ec-2d9f-5639-98b7-fffb53266625','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','Раздача на примере и итоговая памятка','9. Раздача целиком: связываем правила

За столом шесть игроков. Уровень 100/200, анте 200; у всех достаточно фишек. SB вносит 100, BB — 200 как блайнд и ещё 200 как анте. В банке 500.

Первый игрок после BB делает колл 200, остальные до SB сбрасывают карты, SB добавляет 100 до колла 200. Теперь слово у BB. Он делает чек: его ставка уже равна 200, но право на действие у него было. В банк внесено 800: по 200 от трёх живых участников и 200 анте.

Дилер сжигает карту и открывает флоп. Первым действует SB, потому что его рука живая и у него есть фишки. Все трое делают чек. Дилер сжигает карту и открывает тёрн; все снова делают чек. Затем ещё одно сжигание и ривер.

На ривере SB ставит 400, BB и третий игрок сбрасывают карты. SB выигрывает банк без вскрытия. Его непокрытая ставка 400 возвращается ему; разыгрываемый до этой ставки банк составлял 800. Дилер не открывает карты игроков ради определения комбинаций, когда осталась одна живая рука.

ИТОГ БЛОКА

Дилер должен понимать: какие взносы внесены до раздачи, кто действует первым, когда завершены торги, можно ли открывать следующую улицу и кто имеет право на банк. Главное — не скорость открытия карт, а правильная последовательность.

ПРОВЕРЬТЕ СЕБЯ

1. При уровне 100/200 и анте 200 сколько вносит BB с достаточным стеком? Ответ: 400, из них 200 — ставка BB и 200 — анте.
2. Сколько доплачивает до колла BB игрок, который ещё ничего не ставил? Ответ: 200, а не 400.
3. SB сбросил карты до флопа. Кто действует первым на флопе? Ответ: ближайший слева от BTN игрок, у которого остались живая рука и фишки для действия.
4. В игре вдвоём кто действует первым? Ответ: на префлопе BTN/SB, после флопа — BB.',NULL,'[]'::jsonb,'[]'::jsonb,4,true,false,true),
('a5c1f6cd-726b-5959-b5a7-43753869c301','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','Действия игрока и безлимитная игра','После этого блока вы сможете различать действия игрока, считать минимальный полный рейз, понимать базовый смысл олл-ина и замечать ситуации, где нельзя определять действие только по количеству выставленных фишек.

1. Что означает No-Limit

В безлимитном Техасском холдеме игрок может поставить вплоть до всех своих фишек. Но «безлимитный» не означает «без правил»: сохраняются очередность действий, минимальный размер полной ставки и рейза, требования к объявлениям.

Участник играет фишками своего стека. Нельзя докладывать новые фишки из кармана посреди раздачи для покрытия ставки. Вопросы турнирного стека, штрафов и пересадок решаются по регламенту, а не по договорённости участников во время торгов.

2. Пять основных действий

Чек (check) — остаться в раздаче без внесения новых фишек, когда перед игроком нет неуравненной ставки. Это не выход из раздачи. На префлопе BB также может сделать чек, если до него были только коллы его полного блайнда.

Бет (bet) — первая добровольная ставка на улице, когда до игрока ещё нет ставки. На префлопе BB уже задаёт исходную ставку: увеличение её размера называется рейзом.

Колл (call) — уравнять текущую ставку с учётом уже внесённых на этой улице фишек. Если ставка 600, а игрок уже внёс 200 на этой улице, полный колл требует добавить 400. При недостаточном стеке возможен колл олл-ин меньшей суммой.

Рейз (raise) — увеличить текущую ставку. Повторный рейз называют ререйзом; это не отдельное действие с другой математикой.

Фолд (fold), или пас, — отказаться от дальнейшего участия в раздаче. Ранее внесённые фишки остаются в банке. Когда перед игроком есть ставка, нельзя заменить решение «колл или фолд» словом «чек».',NULL,'[]'::jsonb,'[]'::jsonb,0,true,false,true),
('dda6b8cf-902d-5f2a-835f-fd746904339d','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','Минимальное повышение и олл-ин','3. Минимальная ставка и минимальный рейз — разные вещи

Минимальная полная открывающая ставка в No-Limit равна BB текущего уровня. При BB 200 первая полная ставка на флопе — не меньше 200. Исключение: игрок может поставить оставшиеся 150 олл-ин. Это неполная ставка, а не изменение BB для остальных.

Для расчёта минимального полного рейза нужно знать не только текущую общую ставку, но и величину последнего полного увеличения на этой улице.

Формула: минимальная новая общая ставка = текущая общая ставка + величина последнего полного повышения.

Пример на префлопе при блайндах 100/200:
• Игрок повышает с 200 до 600. Полное увеличение составило 400.
• Следующий минимальный полный рейз — до 1000: текущие 600 плюс увеличение 400.
• Это не обязательно удвоение до 1200. Считать надо величину повышения, а не механически умножать текущую ставку на два.

Другой пример, на флопе:
• Первая ставка — 300. До этого на улице все ставки были нулевыми.
• Минимальный полный рейз — до 600.
• Если после рейза до 600 следующий игрок повышает до 900, величина его полного повышения — 300; следующий минимум — до 1200.

Поэтому фраза «ставка 300» без описания улицы и предыдущих действий недостаточна для разбора сложного примера.

4. Олл-ин и короткий стек

Олл-ин (all-in) — ставка всех оставшихся фишек. Олл-ин может быть первой ставкой, коллом, полным рейзом или неполным повышением: само слово не определяет тип действия.

После олл-ина у игрока нет фишек для последующих ставок, но его живая рука продолжает участвовать в розыгрыше доступных ему банков. Игрок с коротким стеком не может выиграть ту часть ставок соперников, которую не покрывал своим вкладом. Отдельно учитываются анте и другие мёртвые деньги по правилам формирования банков.

Пример без анте, блайндов и других вкладов: трое игроков внесли 300, 1000 и 1000. Основной банк — 900, по 300 от каждого. Сайд-пот — 1400, по 700 от двух игроков с большими вкладами. Игрок с вкладом 300 претендует только на основной банк. Два остальных могут выиграть основной банк и сайд-пот, пока их руки живые.

Фишки, сброшенные игроками в пас, не исчезают из банка. Непокрытый никем из соперников остаток ставки не образует «банк с одним участником», а возвращается поставившему. Подробная практика формирования банков будет в разделе «Фишки и банки».

Если неполный олл-ин меньше минимального полного повышения, это не делает его полным рейзом. Например, после ставки 1000 олл-ин другого игрока до 1300 увеличивает сумму на 300, а не на необходимые 1000. Такое действие само по себе не возвращает право рейза тому, кто уже действовал и не столкнулся с полным повышением. Несколько коротких олл-инов и права каждого участника требуют отдельного разбора последовательности действий; при сомнении вызывайте флора до продолжения игры.',NULL,'[]'::jsonb,'[]'::jsonb,1,true,false,true),
('7034af59-922c-5eeb-8bd1-e99f4cbdf84b','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','Объявления, одна и несколько фишек','5. Объявления: сначала понять действие, потом двигать фишки

Ясное объявление в свой ход имеет значение для действия игрока. Дилер должен услышать объявление и не заменять его собственной догадкой по жесту или выражению лица.

Для обучения используем недвусмысленные формулировки: «колл», «пас», «рейз до 1000», «олл-ин». Важно различать общую сумму ставки и количество добавляемых фишек.

Пример: игрок уже поставил 200 и ясно объявил «рейз до 1000». Его общая ставка на этой улице должна составить 1000, то есть нужно добавить 800. Ранее внесённое анте не вычитается из суммы ставки.

Слова «колл» с последующей попыткой выставить больше фишек не превращаются автоматически в рейз. Если слова и фишки расходятся, объявление не расслышано или сумма двусмысленна, остановите дальнейшее развитие ситуации и восстановите факты. При споре решение принимает флор.

Не предлагайте игроку выбрать желаемое действие задним числом после того, как стали известны реакции соперников.

6. Одна крупная фишка

Рассмотрим простой случай: перед игроком ставка 500, своих ранее выставленных фишек на этой улице у него нет. В свой ход он молча ставит одну фишку 1000, не объявляя рейз. Это колл 500, а не автоматическое повышение до 1000. Излишек 500 возвращают как сдачу.

Но правило нельзя сокращать до «одна фишка всегда колл». Если на улице перед игроком вообще нет ставки и он первым ставит одну фишку 1000, это открывающая ставка 1000 при допустимом размере.

Если ранее уже были выставлены фишки, объявлен рейз, либо использовано несколько фишек, требуется учитывать все условия. Не применяйте пример с одной фишкой механически к другой ситуации.

7. Несколько фишек и ставка несколькими движениями

Несколько фишек без объявления не означают автоматический рейз. Сначала определяют сумму колла и смотрят на номиналы. В следующих примерах у игрока нет ранее выставленных на этой улице фишек, он действует в свой ход, не объявлял рейз, имеет достаточно фишек и не находится в олл-ине.

Пример: перед игроком ставка 1200. Он молча ставит две фишки по 1000. Если убрать одну из них, оставшихся 1000 недостаточно для колла 1200. Поэтому две необходимые для покрытия ставки фишки означают колл 1200 со сдачей 800, а не автоматический рейз до 2000.

Иной случай: перед игроком первая ставка улицы 1000, он молча выставляет три фишки по 500 — всего 1500. Одна фишка может быть убрана, а оставшихся 1000 всё равно хватит для колла. Здесь проверяют величину повышения. Минимальное полное повышение после ставки 1000 составляет ещё 1000, то есть общий минимум — 2000. Фактически внесённое повышение 500 достигает 50% от этого увеличения. По стандартному правилу неполного повышения без олл-ина игрок должен довести рейз до 2000.

Для сравнения: при тех же условиях игрок ставит 1400 фишками 1000 + 100 + 100 + 100 + 100. Повышение всего 400, меньше 50% от необходимой 1000; без предварительного объявления рейза это колл 1000 со сдачей 400.

Порог 50% относится к ВЕЛИЧИНЕ ПОВЫШЕНИЯ, а не к половине банка и не к половине общей новой ставки. Нельзя применять его до проверки правила одной фишки или необходимых для колла нескольких фишек. В ситуациях с прежними фишками, несколькими олл-инами или неоднозначным объявлением требуется отдельный разбор; при споре — флор.

Чтобы действие было ясным, игрок может заранее объявить полную сумму допустимой ставки и затем выставить её. Без ясного предварительного объявления нельзя бесконечно добавлять фишки несколькими движениями, подстраивая ставку под реакцию соперников. Это риск стринг-бета — ставки или повышения в несколько приёмов.

Не следует считать любое второе движение руки нарушением без проверки того, что было ясно объявлено до перемещения фишек. При споре дилер описывает факты флору, а не спорит с игроком о его предполагаемом намерении.',NULL,'[]'::jsonb,'[]'::jsonb,2,true,false,true),
('04de6f88-0dcd-5b39-ad84-ce23359e130c','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','Контроль торгов и расчёт добавки','8. Что дилер контролирует перед продолжением торгов

• Действует ли игрок в свою очередь.
• Что именно объявлено и сколько фишек выставлено.
• Какова текущая общая ставка и сколько этому игроку осталось добавить для колла.
• Достаточен ли размер полного повышения и есть ли право на него.
• Остались ли участники, которым положено действие.
• Видны ли живые карты и стеки; крупные фишки не должны быть скрыты.

Нельзя открывать следующую улицу только потому, что за столом наступила пауза. Сначала убедитесь, что все необходимые действия завершены.

9. Практика дилера: считать общую ставку, а не только добавку

Блайнды 100/200. Игрок A повышает до 600. Игрок B уже внёс 200 как BB и объявляет «рейз до 1000». Это допустимый минимальный полный рейз: A увеличил ставку на 400, B повышает ещё на 400. B добавляет 800, а не 1000. Анте, которое он внёс до раздачи, в ставку не засчитывается.

Игрок A теперь решает: сбросить карты, добавить 400 до колла 1000 либо сделать допустимый рейз. Торги не завершаются от одного объявления B. Если A коллирует и больше никто не должен действовать, дилер проверяет суммы и завершает круг. Если A выбирает полный рейз, следующий минимум — до 1400, пока промежуточные действия не изменили условия.

ИТОГ БЛОКА

Слова «бет», «колл», «рейз» и «олл-ин» описывают разные вещи. Для правильного решения нужны контекст, очередность и точные суммы. Одна крупная фишка не всегда означает рейз, а неполный олл-ин не всегда открывает торговлю заново.

ПРОВЕРЬТЕ СЕБЯ

1. BB — 200, игрок повышает до 600. Каков следующий минимальный полный рейз? Ответ: до 1000, потому что последнее полное увеличение — 400.
2. На флопе первая ставка 300. Каков минимальный полный рейз? Ответ: до 600.
3. Ставка 600, игрок уже внёс 200 на этой улице. Сколько добавить для полного колла? Ответ: 400.
4. Перед игроком ставка 500; своих фишек на улице нет. Он молча ставит одну фишку 1000. Что это? Ответ: колл 500 со сдачей, если до этого не объявлялся рейз.
5. Можно ли сделать чек, когда перед игроком есть неуравненная ставка? Ответ: нет.',NULL,'[]'::jsonb,'[]'::jsonb,3,true,false,true),
('6f2afb51-1468-5955-b675-085b1020bdd2','1982a9ba-4a13-5932-920b-d7737fca5132','Комбинации: чтение и сравнение рук','После этого блока вы сможете найти лучшую пятикарточную комбинацию, сравнить одинаковые типы рук, определить кикер, заметить игру от борда и правильно распознать деление банка. Для дилера недостаточно назвать «пара» или «флеш»: нужно объяснить результат точными пятью картами.

1. Главное правило: сравниваем пять карт, не семь

В Техасском холдеме игроку доступны две карманные карты и пять общих. Из этих семи выбирают лучшую комбинацию ровно из пяти. Можно использовать две карманные карты, одну или ни одной. Обязанности использовать обе карманные карты в Холдеме нет.

Достоинство — значение карты: двойка, тройка, …, десятка, валет, дама, король, туз. Масть — пики ♠, червы ♥, бубны ♦ или трефы ♣. Туз старше короля; отдельное исключение — младший стрит A–2–3–4–5.

Сначала сравнивают тип комбинации. Только при одинаковом типе переходят к достоинствам составляющих её карт. Пара тузов не выигрывает у тройки двоек лишь потому, что туз старше двойки.

При сравнении равных покерных рук масти преимущества не дают: пики не старше червей, а червы не старше треф. Если все пять сравниваемых достоинств одинаковы, победителей может быть несколько.

2. Старшинство комбинаций

От слабой к сильной:
1) Старшая карта.
2) Пара.
3) Две пары.
4) Тройка.
5) Стрит.
6) Флеш.
7) Фулл-хаус.
8) Каре.
9) Стрит-флеш.

Роял-флеш — название самого высокого стрит-флеша: 10–J–Q–K–A одной масти. Его можно отдельно показывать в учебной таблице, но по правилу сравнения это вершина стрит-флешей.

Запомните соседние ступени: стрит сильнее тройки, флеш сильнее стрита, фулл-хаус сильнее флеша, каре сильнее фулл-хауса. Высота отдельной карты более слабого типа комбинации не меняет эту очередность.

3. Старшая карта, пара и кикер

Старшая карта. Если нет пары и более сильной комбинации, сравнивают лучшие пять карт по убыванию. При равной первой сравнивают вторую, затем третью, четвёртую и пятую до первого различия.

Пример готовых рук: A–K–9–6–3 против A–Q–J–8–4, без флеша и стрита. Тузы равны, следующий K старше Q — первая рука выигрывает. Не нужно складывать значения остальных карт.

Пара. Две карты одного достоинства плюс три лучшие остальные карты. Сначала сравнивают пару. Если пары равны — три оставшиеся карты по старшинству.

Кикер — карта вне основной повторяющейся группы, которая входит в лучшие пять и может решить сравнение. Для пары могут понадобиться все три кикера; для тройки — два; для двух пар и каре — один. У стрита, флеша и фулл-хауса нет дополнительной шестой карты-кикера.

Борд A♥ A♦ 9♣ 6♠ 2♥. Игрок 1: K♣ Q♦. Игрок 2: J♠ 10♣.
У обоих пара тузов. Лучшие пять игрока 1 — A–A–K–Q–9, игрока 2 — A–A–J–10–9. Выигрывает игрок 1: первый различающийся кикер K старше J.

Другой борд: A♥ A♦ K♣ Q♦ 9♠. Игрок 1: 8♣ 7♥. Игрок 2: 6♣ 5♥.
У обоих лучшие пять — A–A–K–Q–9. Карманные 8 и 6 не входят в результат. Банк делится: сравнивать «шестую карту» нельзя.

4. Две пары и тройка

Две пары состоят из старшей пары, младшей пары и одного кикера. Сначала сравнивают старшую пару, затем младшую и только потом кикер.

K–K–3–3–A побеждает Q–Q–J–J–A, потому что старшая пара королей выше пары дам. Кикер не нужен, пока уже найдено различие в парах.

Борд K♥ K♦ 8♣ 8♠ 2♥. Игрок 1: A♣ 3♦; игрок 2: Q♣ J♦. Оба используют общие две пары K–K–8–8. Кикеры — A и Q; выигрывает игрок 1.

Если среди семи карт три пары, отдельной комбинации «три пары» нет. Выбирают лучшие две пары и лучший пятый кикер. Из K–K–Q–Q–2–2–A получаются K–K–Q–Q–A, а не шесть карт с тремя парами.

Тройка — три карты одного достоинства плюс два лучших кикера. При разных тройках выигрывает старшая; при одинаковой сравнивают кикеры.

«Сет» обычно называют тройку, собранную из карманной пары и одной карты борда. «Трипс» — тройку с парой на борде и соответствующей карманной картой. Это способы образования одной комбинации. Сет не сильнее трипса только из-за названия: сравнивают достоинства и лучшие пять.

5. Стрит: последовательность, а не сумма карт

Стрит — пять последовательных достоинств. Масти могут различаться. Повтор достоинства не заменяет недостающую ступень: 5–6–7–7–9 не является стритом.

Стрит сравнивают по старшей карте: 6–7–8–9–10 сильнее 5–6–7–8–9. Если старшая карта равна, стриты равны; карманная карта вне этих пяти не помогает.

Туз бывает младшим в A–2–3–4–5. Это стрит до пятёрки, он проигрывает 2–3–4–5–6. Либо туз старший в 10–J–Q–K–A. «Круговых» стритов Q–K–A–2–3 и K–A–2–3–4 нет.

Борд 6♣ 7♦ 8♠ 9♥ 2♣. Игрок 1: 10♦ 3♠. Игрок 2: 5♥ 4♦.
Игрок 1 имеет стрит до десятки, игрок 2 — до девятки. Побеждает игрок 1. Тройка первого и четвёрка второго не являются кикерами этих стритов.

На борде 5♣ 6♦ 7♥ 8♠ 9♣ у всех уже есть стрит до девятки. Но банк нельзя автоматически делить: карманная десятка улучшит стрит до десятки. Сначала проверьте, не улучшает ли каждый игрок общий борд.

6. Флеш: проверяем пять карт нужной масти

Флеш — пять карт одной масти. Четыре карты одной масти ещё не флеш. Пять карт одного цвета, но разных мастей, тоже не флеш.

Если доступно шесть или семь карт одной масти, выбирают пять старших. При сравнении флешей смотрят все пять по убыванию до первого различия, а не только старшую карту и не общее количество карт нужной масти.

Борд A♥ J♥ 8♥ 3♣ 2♦. Игрок 1: K♥ 4♥. Игрок 2: Q♥ 10♥.
Флеш игрока 1 — A–K–J–8–4, игрока 2 — A–Q–J–10–8. Общий туз не делает руки равными: следующий K старше Q, выигрывает игрок 1.

Если на борде пять червей, карманная черва может заменить младшую общую черву. Но не любая черва улучшает борд: она должна войти в лучшие пять. Шестая черва, оставшаяся вне них, не разрывает равенство.

7. Фулл-хаус, каре и стрит-флеш

Фулл-хаус — тройка и пара. Сначала сравнивают тройку, затем пару. Например, 9–9–9–2–2 сильнее 8–8–8–A–A: тройка девяток выше тройки восьмёрок, несмотря на пару тузов во второй руке.

Борд Q♥ Q♦ 7♣ 7♠ 2♦. Игрок 1: Q♣ 3♥, игрок 2: 7♥ A♠. Первый имеет Q–Q–Q–7–7, второй — 7–7–7–Q–Q. Выигрывает первый.

Если среди семи карт две тройки, для тройки фулл-хауса берут старшую, а для пары — две карты младшей. Из A–A–A–K–K–K–2 лучшая рука A–A–A–K–K, а не «две тройки» или шесть карт.

Каре — четыре карты одного достоинства и кикер. Сначала сравнивают каре; при одинаковом каре, которое в Холдеме будет общим на борде, — лучшую пятую карту.

Борд 9♣ 9♦ 9♥ 9♠ 2♣. Игрок 1: A♥ 3♦, игрок 2: K♥ Q♦. У первого 9–9–9–9–A, у второго 9–9–9–9–K. Игрок 1 выигрывает: общее каре не означает автоматического деления.

Стрит-флеш — пять последовательных карт одной масти. Недостаточно отдельно найти стрит одних мастей и флеш из других пяти карт: оба условия должны выполняться на одном наборе из пяти.

Стрит-флеш сравнивается по старшей карте. Роял-флеш — 10–J–Q–K–A одной масти — самый высокий. Если роял-флеш полностью лежит на борде, все оставшиеся живые руки имеют равную лучшую комбинацию; карманные карты не могут её улучшить.

8. Игра от борда и деление банка

«Играть от борда» — использовать все пять общих карт как лучшую руку, не улучшая их карманными. Это разрешено в Холдеме. Но одинаковая комбинация на борде — начало проверки, не готовый вывод о ничьей.

Проверяйте по порядку:
• Может ли карманная карта улучшить тип комбинации?
• Может ли она улучшить достоинства внутри того же типа — стрит, флеш, пару или кикер?
• Если улучшений нет, совпали ли все пять лучших достоинств у сравниваемых рук?

Если лучшие пять равны, банк делится между всеми равными победителями, имеющими право на этот банк. Масть, размер стека, очередность вскрытия и «у кого выше шестая карта» не дают преимущества.

Разделение нечётной фишки и формирование банков изучаются в блоке о банках. В разных банках победители могут быть разными: самая сильная рука за столом не обязательно имеет право на все фишки.

9. Алгоритм дилера на вскрытии

1) Убедитесь, что торги завершены и правильно предъявлены обе карманные карты претендентов.
2) Посмотрите борд: пары, возможные последовательности, число карт каждой масти.
3) Для каждой живой руки найдите лучшие пять, не ограничиваясь двумя карманными.
4) Сравните тип комбинации, затем нужные достоинства в установленном порядке.
5) Найдите ВСЕ равные лучшие руки. Не останавливайтесь на первом найденном победителе.
6) Проверьте право на конкретный банк. Объявите результат и только затем передавайте фишки.

Слова игрока о его комбинации не заменяют чтение открытых карт. Не объявляйте руку проигравшей лишь потому, что игрок назвал её неверно. Карты, сбросы и спорные права на банк сохраняйте для решения флора, не смешивая всё в мак.

10. Типичные ошибки новичка

• Искать комбинацию из шести или семи карт.
• Считать, что обе карманные карты обязаны войти в руку.
• Видеть одинаковые пары и забывать кикеры.
• Сравнивать карманные карты, не вошедшие в лучшие пять.
• Объявлять деление только потому, что на борде стрит, флеш или каре.
• Давать преимущество масти.
• Считать A–2–3–4–5 самым старшим стритом.
• Читать фулл-хаус по паре, не сравнив тройку.
• Найти одного победителя и не проверить равную руку другого игрока.

ИТОГ БЛОКА

Результат должен объясняться ровно пятью картами. Сначала тип комбинации, затем достоинства в правильном порядке. Нет старшинства мастей, шестого кикера и обязанности использовать обе карманные карты. При совпадении всех пяти — равенство рук; право на каждый банк проверяется отдельно.

ПРАКТИКА

Тренируйтесь на борде и двух-трёх открытых руках. Сначала называйте не победителя, а точные лучшие пять каждой руки. Затем сравнивайте их и объясняйте первое различие. При делении вслух проговаривайте, почему карманные карты не улучшают общую комбинацию. После уверенного чтения переходите к тренажёру определения всех победителей.',NULL,'[]'::jsonb,'[]'::jsonb,0,true,false,true),
('c671c43d-9a87-58b4-b08e-5f495eb35270','f8ebc418-ed9e-50d5-bdec-266a2bf326fc','Работа с колодой: подготовка, тасовка и сдача','После этого блока ученик должен понимать, как подготовить и проверить колоду, выполнить последовательность 2–1–1 и срезку, держать карты под контролем и раздать карманные карты без засветов. Умение объяснить процедуру проверяется тестом; качество движений — отдельно тренером за настоящим столом.

1. Зачем дилеру техника работы с картами

Задача не в том, чтобы красиво и быстро перебрасывать карты. Правильная техника обеспечивает случайный порядок, сохранность колоды, скрытость лицевых сторон и понятную участникам процедуру. Темп появляется после устойчивой точности, а не вместо неё.

До первой раздачи дилер должен знать, какой колодой работает, где лежит подрезная карта и какие места участвуют в раздаче. Рабочая зона должна быть чистой и сухой; посторонние предметы не должны мешать движению карт.

В обычной колоде для Техасского холдема 52 игральные карты: по 13 достоинств каждой из четырёх мастей. Джокеры, рекламные и запасные карты в игровую колоду не входят. Подрезная карта — отдельный аксессуар, а не 53-я карта для раздачи.

2. Проверка колоды: количество, состав и состояние

Представим: дилер получил колоду, пересчитал 52 карты и сразу начал игру. Достаточно ли этого? Нет. Среди 52 могут оказаться две одинаковые карты, отсутствовать другая карта или быть карта с отличающейся рубашкой.

Полная проверка состоит из разных задач:
• Количество: действительно 52 игральные карты, без посторонних вложений.
• Состав: все достоинства четырёх мастей, без дублей и пропусков.
• Состояние: нет повреждений, загибов и заметных отметок, по которым карту можно узнавать.
• Рубашки: карты принадлежат одной колоде и не выделяются рисунком или цветом.

Spread, или спред, — раскладка колоды широким рядом по столу, позволяющая просмотреть карты. При проверке нового комплекта порядок достоинств и мастей помогает убедиться, что состав полный. Если карты не упорядочены, один быстрый взгляд на раскладку не доказывает отсутствия дублей: проверка должна реально установить состав.

Лицевые стороны позволяют проверить достоинства и масти, но одинаковость рубашек нужно проверить отдельно. Нельзя увидеть все рубашки, глядя только на лицевую сторону.

Обнаружена проблема — не начинайте раздачу, не выбрасывайте подозрительную карту и не подменяйте её случайной картой из другого комплекта. Сохраните колоду и сообщите тренеру или флору; замена выполняется по процедуре клуба.

Полный контроль состава, приём колоды и проверка при смене дилера выполняются по регламенту клуба. Не нужно превращать каждую новую раздачу в повторную открытую сортировку всех карт: сначала выполните установленную проверку, затем нужное перемешивание.

3. Рабочая зона: где находятся разные группы карт

До раздачи отделяйте рабочую колоду от использованных и посторонних карт. Во время раздачи различайте:
• Рабочую колоду, из которой ещё будут сдаваться карты.
• Карманные карты игроков.
• Борд — открытые общие карты.
• Сожжённые карты, или бёрны.
• Мак — сброшенные и иные использованные карты в отведённой зоне.

Это не разные виды игральных карт, а разные группы с определённым назначением. Их нельзя смешивать посреди раздачи. Например, сброшенная игроком карта не возвращается в рабочую колоду ради восполнения ошибки.

Конкретные зоны на столе и техника хранения бёрнов показываются тренером. Важно, чтобы дилер сохранял контроль и мог объяснить, откуда взялась каждая группа. Не закрывайте картами номиналы ставок и не отправляйте колоду в зону банка.

4. Хват колоды: контроль без лишнего напряжения

Колода удерживается устойчиво, примерно параллельно сукну, лицевыми сторонами вниз. Пальцы направляют края и не дают пакету рассыпаться. Большой палец должен позволять аккуратно отделять верхнюю карту.

Держать колоду нужно достаточно уверенно для контроля, но без сильного сдавливания и изгиба. Ученик не должен показывать нижнюю карту, когда поднимает колоду, поворачивает кисть или тянется к дальнему месту.

В материалах эта техника называется mechanic’s grip — рабочий хват колоды. Ведущая рука и положение пальцев подбираются с тренером. Леворукому ученику не следует самостоятельно зеркалить всю процедуру, если из-за этого меняются порядок раздачи или контроль карты.

Проверка простая: ученик может отделить одну верхнюю карту, не вытянув две, и вернуть руку в исходное положение, не раскрыв низ колоды. Если пакет перекашивается и карты видны сбоку, скорость нужно снизить.

5. Шеми-шафл: перемешивание на столе

Шеми-шафл, или wash, — перемешивание карт рубашками вверх на поверхности стола. Карты перемещают в разные стороны, не переворачивая, после чего аккуратно собирают в один пакет и выравнивают.

Это не демонстрационный spread: при spread карты показывают для проверки, при wash — смешивают закрытыми. И не замена всем последующим этапам. В исходной процедуре клуба wash используется при подготовке колоды, после чего выполняются предусмотренные тасовки и срезка.

При сборе после wash не должно быть забытых под ладонью карт, отдельной кучки рядом или карты, случайно оставшейся на полу. Потеря контроля важнее экономии нескольких секунд. Если есть сомнение в комплектности, не продолжайте автоматически.

6. Последовательность 2–1–1

В материалах клуба используется схема: два рифла → один стрип → ещё один рифл → срезка. Обозначение 2–1–1 описывает первые четыре действия: 2 рифла, 1 стрип, 1 рифл. Срезка выполняется после них, а не входит вместо последнего рифла.

Рифл (riffle) — колоду делят на два приблизительно равных пакета и контролируемо переплетают их картами. Движение выполняется низко над столом, без раскрытия лиц и сильного выгибания. После врезки пакеты сводят и аккуратно выравнивают.

Стрип (strip) — перекладывание небольших пакетов карт, изменяющее их порядок. Это не срезка двух крупных частей и не ещё одно название рифла. Конкретное направление перекладывания и работу пальцев тренер показывает на настоящей колоде.

Порядок целиком:
1) Первый рифл, затем выравнивание.
2) Второй рифл, затем выравнивание.
3) Стрип, затем сбор и выравнивание.
4) Третий рифл, затем выравнивание.
5) Срезка на подрезную карту по процедуре клуба.

Почему важна последовательность? Повторяемая процедура помогает не пропустить этап и делает действия дилера понятными для контроля. Но сами слова «два рифла» не гарантируют качественного перемешивания, если половины почти не переплелись или часть колоды вообще не участвовала.

В СПЛ ручная подготовка колоды выполняется в последовательности: рифл → рифл → стрип → рифл → срезка. Работа с шафл-машиной изучается отдельно, если она используется за столом.

7. Срезка и подрезная карта

Срезка меняет расположение частей уже перемешанной колоды. Она завершает принятую процедуру подготовки, а не заменяет полноценную тасовку.

Подрезная карта закрывает нижнюю игральную карту от случайного просмотра. Она не участвует в борде, не выдаётся игроку и не считается сожжённой игральной картой.

Срезку выполняют контролируемо на столе, не показывая нижние карты и не унося пакет из рабочей зоны. После неё игральная колода собрана, выровнена и удерживается так, чтобы подрезная карта защищала её низ. Точные размеры снимаемых частей и положение рук отрабатывают по показу тренера; произвольное числовое ограничение в этом уроке не вводится.

После срезки не делайте лишние перестановки карт «для красоты». Если процедура была прервана, пакет рассыпался или возникло сомнение, что он подготовлен правильно, не скрывайте проблему ускоренной раздачей. Сообщите ответственному сотруднику и восстановите процедуру по регламенту.

8. Раздача карманных карт: два круга, а не по две сразу

Перед раздачей установлены позиции и список участвующих мест, внесены нужные обязательные взносы. В СПЛ при трёх и более игроках действует анте BB; сначала оплачивается анте, затем BB. В хедз-апе анте нет. Подробная математика взносов разобрана в «Основах покера».

При обычной раздаче на столе с тремя и более игроками первую карту получает первое участвующее место слева от BTN, обычно SB. Дальше раздают по одной карте каждому по часовой стрелке. Завершив первый круг, таким же порядком выполняют второй.

Нельзя выдать одному игроку сразу две карты, затем перейти к следующему: это меняет порядок распределения колоды. Пустому месту без участника карты не раздают. Вопрос отсутствующего, но ещё участвующего в турнире игрока определяется отдельным правилом присутствия — не приравнивайте его автоматически к пустому месту.

В игре вдвоём BTN одновременно является SB, а первую карманную карту получает BB. Порядок по-прежнему по одной карте за круг, всего две каждому. Не путайте первую карту с первым действием: на префлопе в хедз-апе первым действует BTN/SB.

Перед префлопом в обычной процедуре не сжигают карту. Бёрн выполняют перед открытием флопа, затем перед тёрном и ривером. Подробный порядок борда — в следующем блоке «Полная раздача».

9. Питчинг: карта идёт к игроку, а не летит вверх

Pitching, или питчинг, — управляемая подача одной карты к месту игрока. Карта движется низко, примерно параллельно столу, рубашкой вверх. Задача — доставить её в предусмотренную зону перед игроком, а не попасть в его ладонь или дальний край стола.

Сначала отделяют одну верхнюю карту; затем контролируемым движением направляют её к месту. Работайте без широкого замаха через весь стол. Для дальних и ближних боксов усилие отличается, но высота полёта и сохранность закрытой стороны должны оставаться под контролем.

Не отправляйте карту в стопку фишек, чужую руку или мак. Не пытайтесь компенсировать неточный прицел силой. Если карта переворачивается, тренер проверяет угол, хват, движение и состояние поверхности, а не только просит ученика «быть внимательнее».

Условие хорошей подачи: одна карта, верный адресат, закрытая лицевая сторона, контролируемая траектория. Скорость оценивается только после выполнения этих условий.

10. Если во время подготовки или сдачи произошла ошибка

Карта перевернулась, выпала за стол, выданы две вместо одной, обнаружено повреждение или порядок карт оказался под сомнением — не продолжайте молча, надеясь исправить это позже.

Сохраните расположение и последовательность карт, обозначьте проблему, не давайте ситуации развиваться дальше и привлеките флора или тренера. Не заталкивайте открытую карту обратно в середину колоды и не меняйте её незаметно по собственной инициативе.

Не используйте универсальную формулу «одна открытая — всегда замена, две — всегда новая раздача». Важны момент, место карты, число выданных карт и последующие действия. Решения по открытым картам и перераздаче изучаются в блоке «Ошибки дилера».

Цель этого урока — научиться не создавать ошибку и не усугублять её. Полный разбор нештатных ситуаций не заменяется догадкой по одному признаку.

11. Практика за столом

Упражнение 1. Проверка комплекта.
На учебной, не игровой колоде тренер моделирует пропуск, дубль или постороннюю карту. Ученик должен обнаружить проблему по количеству и составу и назвать правильное первое действие. Заранее согласуйте, что это учебный комплект; не подготавливайте дефектную колоду для настоящей игры.

Упражнение 2. Тасовка по этапам.
Ученик медленно выполняет 2–1–1 и срезку, вслух называя этапы. Тренер следит за раскрытием лиц, участием всего пакета, выравниванием и нижней картой. После устойчивого выполнения названия этапов можно перестать произносить.

Упражнение 3. Подача в боксы.
На сукне отмечают девять учебных зон. Ученик подаёт карты по кругу, регулируя усилие для каждого расстояния. Сначала считают перевороты, промахи и ошибки направления. Тренировка подачи всей колоды в зоны не имитирует правила раздачи одной игровой руки.

Упражнение 4. Два круга на разные составы стола.
Тренер задаёт три, шесть или девять участвующих мест, затем отдельно хедз-ап. Ученик определяет первую карту, делает два круга и проверяет, что у каждого по две карты. Затем повторяет с пустыми местами, заранее обозначенными тренером.

Короткая ежедневная тренировка: несколько минут на хват и выравнивание, затем тасовка и срезка, затем точная подача. Длительность и темп повышают по качеству, не по желанию «сдать быстрее всех». Не отрабатывайте действия вслепую на действующей игре.

ЧТО ПРОВЕРЯЕТ ТРЕНЕР

• Карты не засвечиваются при хвате, тасовке, срезке и подаче.
• Колода не рассыпается, не теряет карты и не смешивается с маком.
• Ученик выполняет 2–1–1 и отдельную срезку без пропусков.
• Подрезная карта используется по назначению.
• Раздача идёт в правильном направлении, по одному за круг.
• Ученик различает первый адресат карты и первого действующего игрока.
• Ошибку замечает и сообщает о ней, а не скрывает.

Точный норматив времени и число повторений утверждает тренер. Тест в приложении проверяет знание порядка, но не подтверждает владение движениями.

ИТОГ БЛОКА

Проверить комплект → при необходимости выполнить установленную подготовку → удерживать колоду закрыто → два рифла, стрип, рифл → срезка → раздать по одной карте за два круга. Сначала контроль и отсутствие засветов, затем плавность и скорость.',NULL,'[]'::jsonb,'[]'::jsonb,0,true,false,true),
('3f294978-18cc-5e17-a036-ece6e326e763','7b0d905a-c40f-555c-b9db-02fabd8f934b','Полная раздача: последовательность действий','Задача блока

Научиться вести одну раздачу от подготовки стола до передачи банка и подготовки следующей раздачи. Главное здесь — последовательность: что проверить, что сделать и только после чего двигаться дальше. Скорость появляется после того, как порядок стал устойчивым.

Этот блок продолжает «Работу с колодой». В том блоке изучается порядок подготовки и сдачи карт. Здесь — порядок всей раздачи, включая ставки, улицы и завершение.

Короткая схема

Проверить стол и позиции → проконтролировать обязательные ставки → подготовить колоду → сдать карманные карты → провести префлоп → собрать завершённые ставки → бёрн и флоп → провести торговлю → собрать ставки → бёрн и тёрн → провести торговлю → собрать ставки → бёрн и ривер → провести торговлю → вскрытие и проверка рук → передать банк → собрать карты и подготовить следующую раздачу.

Это схема обычной раздачи. Если все соперники одного игрока сбросили карты, раздача заканчивается раньше. Если дальнейшие ставки невозможны из-за олл-инов, оставшийся борд выкладывают без лишних кругов торговли, но с обычным бёрном перед каждой улицей.

1. ДО НАЧАЛА: УБЕДИТЬСЯ, ЧТО СТОЛ ГОТОВ

Не начинайте сдавать карты только потому, что предыдущий банк уже передан.

Проверьте: предыдущая раздача завершена; карты собраны и находятся под контролем; банк передан верному получателю; баттон и позиции обязательных ставок определены; понятен состав участников новой раздачи; известен текущий уровень блайндов и анте.

Баттон не двигают механически «на ближайшего человека». При выбывании игрока возможен мёртвый баттон и другие особенности расстановки. Если ситуация неочевидна, сначала уточните позиции, а затем начинайте новую раздачу. Подробный разбор таких случаев — в турнирном блоке.

Отсутствующий участник и свободное место — не одно и то же. Чтобы рука была живой, игрок должен находиться в пределах досягаемости своего стула к моменту окончания исходной сдачи последней карты всем игрокам. Если его нет, рука гасится, смотреть карты нельзя, обязательные взносы остаются в банке. Временно отсутствующий участник не считается выбывшим только из-за пустого стула.

Проверка перед переходом: я понимаю, кому сдаю карты, где баттон, кто ставит SB и BB и какой сейчас уровень.

2. ОБЯЗАТЕЛЬНЫЕ СТАВКИ: ОТДЕЛИТЬ АНТЕ ОТ БЛАЙНДА

В СПЛ большой блайнд платит анте размером в один BB. Сначала оплачивается анте, затем большой блайнд. В хедз-апе анте нет.

Пример: блайнды 100/200, за столом больше двух игроков. Малый блайнд ставит 100. Большой блайнд оплачивает 200 анте и 200 BB. До добровольных действий в банке и обязательных ставках суммарно 500.

Анте — не часть индивидуальной ставки BB в текущем круге. Оно поступает в банк. Живой большой блайнд остаётся перед игроком как ставка префлопа. Игрок без ранее внесённых фишек уравнивает 200, а не 400.

Если у BB всего 250 при блайндах 100/200 и анте 200, сначала 200 направляются в анте, оставшиеся 50 — в живой BB. Сохраните эти части раздельно. Если возникает вопрос о праве короткого игрока на банк, остановите его распределение и пригласите флора; порядок оплаты сам по себе не определяет право на все фишки банка.

Не смешивайте анте с живым блайндом так, чтобы нельзя было понять назначение фишек. Объявляйте назначение и собирайте их раздельно по принятой технике.

Проверка перед переходом: обязательные суммы и их назначение понятны; анте не выдано за ставку, которую должны уравнивать остальные.

3. КОЛОДА И СДАЧА КАРМАННЫХ КАРТ

Подготовьте колоду по изученной процедуре: рифл → рифл → стрип → рифл → срезка. Это последовательность ручной подготовки колоды в СПЛ.

После подготовки не добавляйте произвольные действия «для надёжности». Держите нижнюю карту закрытой и сохраняйте контроль колоды.

Каждому участнику сдают две закрытые карты: сначала по одной за полный круг, затем второй круг. Направление — по часовой стрелке. Перед карманными картами бёрна нет.

При трёх и более участниках первую карту получает первый участвующий игрок слева от баттона, обычно SB. В хедз-апе баттон одновременно является SB, но первую карту получает BB. Не путайте первого получателя карты с первым игроком, который действует в торговле.

Если карта открылась или нарушился порядок сдачи, остановитесь и сохраните ситуацию. Не исправляйте ошибку скрытно и не объявляйте пересдачу по памяти. Порядок исправления зависит от конкретной ошибки и регламента.

Проверка перед переходом: карты розданы в правильном порядке, у каждого участника нужное число карт, явная ошибка не осталась без внимания.

4. ПРЕФЛОП: ПРОВЕСТИ КРУГ ТОРГОВЛИ ДО КОНЦА

При трёх и более участниках первым действует первый игрок в раздаче слева от BB. В хедз-апе первым действует баттон/SB.

Отслеживайте очередь, объявления и внесённые суммы. Ставки текущего круга должны оставаться различимыми, пока это нужно для проверки колла, повышения и возврата лишней части ставки.

Пример без повышения: блайнды 100/200. Игрок уравнял 200, SB добавил 100. BB ещё должен получить возможность действовать. Если он объявляет чек, круг может завершиться. Если повышает, торговля продолжается.

«Все сходили один раз» не означает, что круг закончен. После повышения действие должно вернуться к тем, кому требуется ответить на новую сумму. Игроки, которые продолжают раздачу и не находятся в олл-ине, должны завершить необходимые действия и уравнять требуемую сумму.

Не используйте взгляд, молчание или движение руки к колоде вместо проверки завершения торговли.

Проверка перед переходом: нет игрока, который ещё должен принять решение; нет неразобранной ставки или спорного действия.

5. ЗАКРЫТЬ КРУГ И СОБРАТЬ СТАВКИ

Сначала завершите торговлю, затем организуйте фишки и только после этого переходите к борду.

Если есть неуравненная часть ставки, её возвращают поставившему игроку. Она не превращается в выигрыш и не остаётся в банке.

Пример: на ривере игрок A ставит 1 000, у B осталось 600, B идёт в олл-ин, других участников нет. Из новой ставки A только 600 уравнены. Лишние 400 возвращаются A. В банк этого круга поступают 600 от A и 600 от B.

Если есть олл-ины с разными суммами, сначала сохраните понятное разделение вкладов и правильно сформируйте основной и побочные банки. Не сгребайте всё в одну кучу с мыслью «потом посчитаю». Подробная математика будет в блоке о банках.

Сброшенные карты держите отдельно от живых рук, колоды и бёрна. Не тянитесь за защищённой рукой игрока, который продолжает раздачу.

Проверка перед переходом: лишние фишки возвращены, суммы и право участия в банках понятны, торговля действительно закрыта.

6. ФЛОП: СНАЧАЛА БЁРН, ЗАТЕМ ТРИ ОБЩИЕ КАРТЫ

Только после завершённого префлопа сожгите одну верхнюю карту закрыто в предназначенную зону, затем выложите три карты флопа по принятой технике.

Бёрн — отдельная закрытая карта. Он не входит в борд и не выдаётся игрокам. Флоп — три общие карты, а не три отдельных улицы.

Дайте игрокам увидеть борд, затем контролируйте начало торговли. После флопа первым действует первый оставшийся в раздаче игрок слева от баттона, который ещё может действовать. Игроков в олл-ине и сбросивших карты пропускают. В хедз-апе первым действует BB, если он ещё может делать ставки.

Далее повторяется рабочий цикл: очередь → объявления → суммы → завершение торговли → организация ставок.

Проверка перед переходом: флоп состоит из трёх карт, перед ним был один бёрн, торговля на флопе завершена.

7. ТЁРН: НЕ ОБГОНЯТЬ ПОСЛЕДНЕЕ ДЕЙСТВИЕ

После завершения торговли на флопе и сбора ставок сожгите следующую верхнюю карту закрыто, затем откройте одну карту тёрна. На борде теперь четыре общие карты.

Начните следующий круг торговли в той же логике: первым действует первый доступный для действия участник слева от баттона.

Нельзя открывать тёрн, пока игрок ещё думает над ответом на ставку флопа. Если дилер уже знает, что «скорее всего будет колл», это не завершает действие игрока.

Проверка перед переходом: перед тёрном был отдельный бёрн; на борде четыре карты; все необходимые решения на тёрне приняты.

8. РИВЕР: ПОСЛЕДНЯЯ КАРТА НЕ ОЗНАЧАЕТ КОНЕЦ РАЗДАЧИ

После завершения торговли на тёрне организуйте ставки, сожгите одну карту и откройте ривер. Теперь на борде пять общих карт.

Проведите последний круг торговли. Не начинайте читать руки и делить банк, пока кто-то ещё должен ответить на ставку.

При обычном полном борде всего выполнены три бёрна: перед флопом, перед тёрном и перед ривером. Перед карманными картами бёрна нет. Перед вскрытием дополнительный бёрн не делают.

Проверка перед переходом: торговля на ривере завершена, неуравненные суммы возвращены, можно переходить к вскрытию.

9. ДВЕ ВЕТКИ, КОТОРЫЕ МЕНЯЮТ ОБЫЧНЫЙ ПОРЯДОК

Ветка А. Остался один игрок.

Если все его соперники сбросили карты, не нужно открывать оставшийся борд и устраивать обычное сравнительное вскрытие. Проверьте завершённость действий, верните неуравненную часть ставки, если она есть, и передайте банк единственному оставшемуся участнику. Не требуйте показывать карты просто из любопытства; специальные требования раскрытия решаются по регламенту.

Ветка Б. Дальнейших ставок быть не может.

Если есть олл-ин и всё действие завершено, руки участников вскрывают по турнирному регламенту. Перед автоматическим выкладыванием остатка борда убедитесь, что среди оставшихся игроков действительно некому продолжать торговлю друг с другом.

Один игрок в олл-ине не останавливает торговлю остальных. Если у двух других участников остаются фишки, они могут продолжать игру за побочный банк.

Когда дальнейших ставок действительно нет, завершайте борд с обычной последовательностью бёрнов и улиц. Не выкладывайте сразу все недостающие карты без бёрнов. Открытые руки и борд должны оставаться читаемыми до определения результата.

10. ВСКРЫТИЕ: СНАЧАЛА ПРОЧИТАТЬ РУКИ, ПОТОМ ПЕРЕДАТЬ БАНК

При обычном вскрытии соблюдайте установленный порядок показа. Обычно после ставки или повышения на ривере первым показывает последний агрессор этой улицы; если на ривере все прочекали — первый участник слева от баттона. Не переносите автоматически агрессию с предыдущей улицы. Для олл-ина действует обязательное раскрытие по регламенту, а не ожидание обычной очереди показа в конце.

Не объявляйте руку мёртвой и не решайте спор о праве на банк самостоятельно в неоднозначной ситуации: сохраните карты и пригласите флора.

Для чтения руки обе карманные карты должны быть открыты и видны. Составьте лучшую пятикарточную комбинацию из семи доступных карт. Название, произнесённое игроком, не заменяет чтение фактических карт.

Например, игрок сказал «пара», но его открытые карты вместе с бордом дают стрит. Оценивается стрит, а не оговорка игрока.

Сравните все претендующие руки. При равенстве лучших пяти карт банк делится. При нескольких банках победителя определяют отдельно среди участников, имеющих право на каждый конкретный банк.

Сохраните борд и открытые руки читаемыми на время проверки и передачи банков. Не смешивайте претендующие карты с маком, пока результат не установлен. Конкретные движения по уборке проигравших рук отрабатываются с тренером так, чтобы не терять возможность проверить решение.

Проверка перед переходом: прочитаны все нужные руки, результат понятен, у каждого банка определены правильные получатели.

11. ПЕРЕДАТЬ БАНК И ТОЛЬКО ПОТОМ ГОТОВИТЬ НОВУЮ РАЗДАЧУ

Объявите результат понятно и без лишних комментариев об игре участников. Передайте банк или банки соответствующим победителям. При делении проверьте суммы; нечётная фишка в минимальном игровом номинале передаётся первому из победителей соответствующего банка слева от баттона по часовой стрелке.

Убедитесь, что фишки дошли нужным игрокам. Не начинайте новую тасовку, если осталась претензия к результату или непереданный побочный банк.

После завершения расчёта соберите карты предыдущей раздачи по принятой технике. Верните рабочие зоны в исходное состояние, определите баттон и обязательные ставки следующей раздачи и снова пройдите начальные проверки.

Если спор возник до завершения передачи, остановите действия и сохраните проверяемую ситуацию. Быстро убрать карты — не способ закончить спор.

12. ОДНА ПОЛНАЯ РАЗДАЧА НА ПРИМЕРЕ

Три игрока: A — баттон, B — SB, C — BB. Блайнды 100/200, анте BB 200. У всех достаточно фишек.

1. Дилер проверяет позиции и обязательные ставки: B — 100, C — 200 анте и 200 BB. Анте отделено от живого блайнда.
2. Подготавливает колоду. Сдаёт по одной карте B, C, A, затем снова B, C, A. Перед этой сдачей бёрна нет.
3. Префлоп: A уравнивает 200, B добавляет 100, C объявляет чек. Только теперь круг завершён. Общая сумма: 200 анте + 200 от каждого из трёх игроков = 800.
4. Дилер собирает завершённые ставки. Выполняет бёрн и открывает три карты флопа.
5. На флопе первым действует B: чек. C — чек. A — чек. Все необходимые действия завершены, банк остаётся 800.
6. Дилер выполняет бёрн и открывает тёрн. B ставит 400, C сбрасывает карты, A уравнивает 400. Торговля завершена, в банк добавляется 800. Всего 1 600.
7. Дилер собирает ставки, выполняет бёрн и открывает ривер. B — чек, A — чек. Только теперь переход к обычному вскрытию.
8. На ривере агрессора не было: первым показывает B, затем A. Дилер читает лучшие пять карт каждого, определяет результат и передаёт банк 1 600 победителю либо делит его при равенстве.
9. После завершения расчёта собирает карты и готовит следующую раздачу.

В этом примере важны не только карты. Важна цепочка: завершить действие → проверить ставки → открыть следующую улицу. Ни одного перехода «на опережение».

13. ЧТО ОТРАБОТАТЬ С ТРЕНЕРОМ

Первый прогон — медленно, с проговариванием каждого шага. Второй — без подсказок, но с тем же порядком. Ускорение — только после устойчивого выполнения.

Отдельно разыграйте пять сценариев: обычная раздача до вскрытия; все сбросили на префлопе; повышение BB после нескольких коллов; олл-ин одного игрока при двух участниках с фишками; хедз-ап без анте.

Тренер проверяет не артистичность и не секунды, а отсутствие пропущенных действий: правильные позиции, обязательные ставки, порядок сдачи, очередь торговли, завершение круга, бёрны, сохранность рук, чтение результата и передачу банка.

Итоговая памятка

Не открыл карту раньше времени. Не забрал фишки до понимания ставок. Не забыл BB после коллов. Не пропустил торговлю из-за чужого олл-ина. Не убрал доказательства до проверки результата. Не начал следующую раздачу, пока не закончил предыдущую.

После блока — отдельный тест на порядок действий. Практическую работу рук и ведение живого стола оценивает тренер; онлайн-тест этого не заменяет.',NULL,'[]'::jsonb,'[]'::jsonb,0,true,false,true),
('32fdbe24-14de-5242-b8c8-df308af622cd','575ebe8d-f77f-5fc3-9759-8209f1a5204f','Номиналы, стопки и нарезка фишек','Задача блока

Научиться проверять суммы, понятно раскладывать фишки, рассчитывать добавление и сдачу и собирать завершённые ставки без потери информации. Сначала точность и понятный порядок, затем скорость.

В турнире фишки обозначают турнирные единицы, а не обязательно рубли. В примерах используются условные номиналы. Цвета и реальные номиналы фишек СПЛ нужно сверить с комплектом клуба: одинаковый цвет в разных комплектах не гарантирует одинаковый номинал.

Главная последовательность

Услышать объявление и увидеть действие → определить, что это за действие → проверить внесённые фишки → установить итоговую сумму ставки → рассчитать добавление, сдачу или возврат → сохранить ставки различимыми до завершения торговли → собрать завершённые ставки и организовать банк.

Не начинайте со сдачи только потому, что увидели крупную фишку. Сначала нужно понять действие игрока.

1. НОМИНАЛ, КОЛИЧЕСТВО И СУММА — ТРИ РАЗНЫХ ВЕЩИ

Номинал — стоимость одной фишки в турнирных единицах. Количество — сколько фишек лежит в группе. Сумма — номинал, умноженный на количество.

Пять фишек по 100 — это 500. Пять по 500 — уже 2 500. Высота стопки похожа, сумма разная.

Смешанный набор считают по номиналам, а затем складывают результаты. Например: две фишки по 1 000, три по 500 и четыре по 100. Получается 2 000 + 1 500 + 400 = 3 900.

Не объявляйте сумму по общему размеру кучи. Сначала убедитесь, какие номиналы в ней есть. Фишка другого номинала внутри одинаковой стопки меняет результат.

Проверка перед переходом: я вижу не просто «несколько фишек», а номиналы, количество и проверяемую сумму.

2. КАК СДЕЛАТЬ СУММУ ВИДИМОЙ

Разделите смешанные фишки по номиналам. Разложите одинаковые фишки в небольшие проверяемые группы, например по пять, и отдельно положите остаток. Конкретную технику и расположение групп показывает тренер.

Пример: нужно проверить 17 фишек по 100. Разложите три группы по пять и остаток из двух. Сумма: 500 + 500 + 500 + 200 = 1 700.

Второй пример: три фишки по 1 000, четыре по 500 и две по 100. Сумма 3 000 + 2 000 + 200 = 5 200. Важно, чтобы другой человек мог проверить расчёт по раскладке, а не только поверить объявлению дилера.

Не прячьте мелкие номиналы за крупными стопками и не закрывайте рукой фишки дольше, чем требуется для действия. Во время пересчёта не смешивайте чужие ставки между собой.

Оценка высоты стопки помогает ориентироваться, но не заменяет точную проверку спорной суммы. Разные фишки и неровные стопки могут выглядеть обманчиво.

3. НАРЕЗКА ФИШЕК: НЕ ТРЮК, А СПОСОБ ПРОВЕРКИ

Нарезка — разделение стопки на одинаковые группы контролируемыми движениями. Её смысл — сделать количество понятным и ускорить повторяемый счёт.

Для начала возьмите 20 одинаковых фишек. Под контролем тренера разделите их на четыре группы по пять. Проверьте каждую группу. Соберите обратно и повторите. Затем отработайте группы по четыре.

Не заучивайте движение с неверным количеством. Если получились группы 5, 5, 4 и 6, сумма может остаться прежней, но навык нарезки пока нестабилен.

Сначала выполняйте упражнение медленно и с визуальной проверкой. Работа на ощупь — последующий тренировочный этап, а не разрешение считать реальные спорные ставки вслепую.

Во время живой игры не подбрасывайте фишки и не делайте декоративных движений, мешающих проверке. Устойчивая низкая раскладка полезнее эффектной высокой башни.',NULL,'[]'::jsonb,'[]'::jsonb,0,true,false,true),
('bb4968bc-eb83-5552-aa1c-4066f45fa2c7','575ebe8d-f77f-5fc3-9759-8209f1a5204f','Объявленная сумма и расчёт добавки','4. ОБЪЯВЛЕНИЕ И ФИШКИ: СНАЧАЛА ОПРЕДЕЛИТЬ ДЕЙСТВИЕ

Одна и та же фишка может иметь разный смысл в разных обстоятельствах.

Пример А: игрок сталкивается со ставкой 600, ранее в этом круге ничего не вносил и молча ставит одну фишку 1 000. В стандартной ситуации это колл 600, а не автоматический рейз до 1 000. Сдача — 400.

Пример Б: игрок в свою очередь сначала ясно объявляет «рейз до тысячи», а затем ставит фишку 1 000. Если повышение до 1 000 допустимо по текущим ставкам, это уже не молчаливый колл. Прежде чем считать сдачу, нужно проверить объявленное действие и законность суммы.

Пример В: на новой улице ставки ещё не было, игрок молча ставит одну фишку 1 000. Это первая ставка 1 000, если она допустима, а не «колл, потому что одна фишка».

Правило одной крупной фишки разбирается в контексте ответа на ставку. Не переносите его на любые движения с одной фишкой. Правила нескольких фишек, неясных объявлений и недостаточных повышений подробно изучаются в блоке «Ставки и объявления».

Если объявление не расслышано или действие неоднозначно, не выдавайте сдачу и не сгребайте ставку наугад. Сохраните ситуацию и уточните действие по регламенту; при споре пригласите флора.

Проверка перед переходом: я установил, что это — колл, ставка, повышение или олл-ин, а не просто посчитал выдвинутые фишки.

5. «ДО СУММЫ» И «ДОБАВИТЬ СУММУ»

Итоговая ставка и количество добавляемых фишек — не одно и то же.

Формула: нужно добавить = требуемая итоговая сумма в текущем круге − уже внесённая игроком живая ставка этого круга.

Пример: блайнды 100/200. Повышений не было, SB хочет уравнять. У него уже внесено 100, поэтому он добавляет 100, а его итоговая ставка становится 200.

Другой пример: SB уже поставил 100, перед ним повышение до 700. Для колла ему нужно добавить 600, а не 700.

Ещё пример: игрок внёс 300 в текущем круге, затем ставка повышена до 1 100. При колле он добавляет 800. Его общий вклад этого круга — 1 100.

Фишки из предыдущих улиц не вычитают из нового колла. Если игрок внёс 600 на префлопе, а на флопе сталкивается со ставкой 400, прежние 600 не оплачивают новую ставку. Если на флопе он ещё не ставил, для колла нужно внести 400.

Анте тоже не является частью живой ставки, которую можно зачесть в колл. При BB 200 и анте 200 большой блайнд имеет живую ставку 200, а не 400.',NULL,'[]'::jsonb,'[]'::jsonb,1,true,false,true),
('75b279b0-4466-5209-980b-f7d2ef41a6f9','575ebe8d-f77f-5fc3-9759-8209f1a5204f','Сдача и размен','6. СДАЧА: РАЗНИЦА МЕЖДУ ВНЕСЁННЫМ И ТЕМ, ЧТО НУЖНО ОСТАВИТЬ

Сначала установите действие и требуемую сумму. Затем проверьте уже внесённую ставку игрока и сколько он добавил. Только после этого рассчитывайте сдачу.

Пример: требуется колл 600, ранее игрок ничего не ставил, молча внёс одну фишку 1 000. В банк по его коллу должно поступить 600, сдача — 400.

Пример с прежней ставкой: у SB уже 100, требуется колл до 700. Игрок объявил колл и добавил фишку 1 000. Из добавленного требуется 600, сдача — 400. Итоговая ставка игрока: прежние 100 + новые 600 = 700.

Общий способ проверки: прежняя ставка + добавленные фишки − сдача = требуемая итоговая ставка.

Не выдавайте сдачу дважды: сначала из ранее внесённых фишек, а потом ещё раз из новой крупной фишки. Раскладка должна позволять восстановить весь расчёт.

Момент выдачи сдачи и использование уже доступных мелких фишек отрабатываются по процедуре клуба. Не забирайте произвольную сумму из защищённого стека игрока и не используйте фишки другого игрока как безымянный запас.

Если мелких номиналов пока нет под рукой, обозначьте, кому и сколько причитается, и действуйте по принятой процедуре размена. Не теряйте обязательство выдать сдачу при переходе к следующему действию.

7. РАЗМЕН: ОБЩАЯ СТОИМОСТЬ НЕ МЕНЯЕТСЯ

Размен меняет номиналы, но не увеличивает стек и не является сам по себе ставкой. Однако выдвижение фишек в свой ход может иметь игровые последствия: нельзя автоматически признать любое движение «просто разменом» задним числом.

Сначала должно быть понятно, что происходит по регламенту: ставка, сдача после колла или разрешённый размен. При неясности остановитесь до перемещения фишек.

Пример отдельного согласованного размена: одна фишка 1 000 заменяется одной по 500 и пятью по 100. Проверка: 500 + 500 = 1 000.

Ошибка: вместо пяти фишек по 100 выдано четыре. Получатель получил 900 вместо 1 000. Нельзя считать размен верным только потому, что количество мелких фишек выглядит привычно.

Во время размена оставляйте исходную крупную фишку различимой до проверки эквивалентной суммы. Не смешивайте её сразу с банком. Источник мелких фишек, порядок обмена и право дилера выполнять его определяются клубной процедурой.

Чип-рейс и изъятие номиналов из игры — отдельные турнирные процедуры. Обычный размен во время раздачи их не заменяет.',NULL,'[]'::jsonb,'[]'::jsonb,2,true,false,true),
('22e259cf-8d79-5f55-8dc1-a3b5b0e56d41','575ebe8d-f77f-5fc3-9759-8209f1a5204f','Подсчёт олл-ина, сбор ставок и возврат','8. ОЛЛ-ИН: ПРОВЕРИТЬ ПОЛНУЮ СУММУ, А НЕ ТОЛЬКО КРУПНЫЕ ФИШКИ

При необходимости точного счёта отделите фишки по номиналам, раскройте скрытые мелкие группы и посчитайте весь заявленный вклад. Не начинайте с предположения, что олл-ин равен размеру самой заметной стопки.

Пример: две по 1 000, три по 500, четыре по 100. Олл-ин составляет 3 900.

Если у игрока уже было 300 в текущем круге и он объявил олл-ин, добавив оставшиеся 1 700, его итоговая ставка этого круга — 2 000. Объявление «олл-ин две тысячи» относится к общей сумме, а не к дополнительным 2 000 сверх прежних 300.

Отличайте точную сумму олл-ина от того, сколько должен добавить конкретный соперник: у соперника тоже могут быть ранее внесённые фишки текущего круга.

Не касайтесь оставшегося стека без необходимости и не превращайте оценку «примерно столько» в официально объявленную точную сумму. Доступные запросы на пересчёт стека и обязанности дилера зависят от правил игры; отдельный произвольный пересчёт любого стека не является обязательным после каждого вопроса.

9. СБОР СТАВОК: СОХРАНИТЬ ИНФОРМАЦИЮ ДО КОНЦА ТОРГОВЛИ

Пока круг не завершён, суммы игроков должны быть различимы настолько, чтобы можно было проверить колл, повышение, недостающие фишки и возврат лишнего.

Не сгребайте всё в центр сразу после первого колла. Если возникнет вопрос, кто сколько внёс, восстановить действие будет сложнее.

Перед сбором проверьте:
— всем ли, кому нужно, предоставлено действие;
— установлены ли итоговые суммы;
— нет ли неуравнённой части;
— учтена ли сдача;
— нет ли олл-инов, требующих разделения банков.

Только после этого собирайте завершённые ставки. Вклады уже сбросивших игроков не возвращают им просто из-за фолда: эти фишки остаются частью разыгрываемых банков.

При разных олл-инах не смешивайте все вклады без расчёта. Здесь важно сохранить суммы и участников; точное формирование основного и побочных банков будет следующим блоком.

10. НЕУРАВНЁННАЯ ЧАСТЬ — ЭТО ВОЗВРАТ, А НЕ СДАЧА ПО КОЛЛУ

Сдача возникает, когда игрок оплатил установленную сумму более крупными фишками. Возврат неуравнённой части означает, что на часть его ставки никто не ответил.

Пример: A ставит 1 200, B имеет всего 800 и уравнивает олл-ином, других игроков нет. Только 800 ставки A уравнены. Ему возвращают 400. В этом круге в банк поступает 800 от A и 800 от B.

Не называйте вернувшиеся 400 отдельным выигранным побочным банком. Другой участник на эти 400 не претендовал.

Если есть дополнительные игроки и другие вклады, нельзя считать возврат только по самому короткому стеку. Часть ставки может быть уравнена третьим участником и образовать побочный банк. Сначала учитывают всех участников и суммы, затем определяют возврат.

Проверка перед переходом: возвращается именно неуравнённая часть, а не законная часть основного или побочного банка.',NULL,'[]'::jsonb,'[]'::jsonb,3,true,false,true),
('b9889a5d-07c4-5d61-be7a-bd0b7b195c95','575ebe8d-f77f-5fc3-9759-8209f1a5204f','Проверка банка и практика счёта','11. ПОДСЧЁТ ПОСТУПЛЕНИЙ В БАНК

Для контроля можно отдельно считать вклад каждого завершённого круга, а затем прибавлять его к уже сформированному банку. При этом ни анте, ни старые ставки не учитываются повторно.

Пример: три игрока, блайнды 100/200, BB-анте 200. Все трое завершают префлоп итоговой живой ставкой 200. Получается 3 × 200 + 200 анте = 800. SB 100 и BB 200 уже входят в эти итоговые ставки: отдельно ещё раз их не прибавляют.

На флопе один игрок ставит 300, второй уравнивает, третий сбрасывает, ничего не внеся на флопе. Добавляется 600, всего 1 400.

На тёрне оба чекают: добавляется ноль, банк остаётся 1 400.

На ривере один ставит 1 000, второй может ответить только 600 и уравнивает олл-ином. Лишние 400 возвращаются поставившему. Добавляется 1 200, итоговый банк — 2 600.

Частая ошибка — прибавить все выдвинутые 1 600 ривера и забыть вычесть возвращённые 400. Считать нужно то, что действительно остаётся в разыгрываемом банке.

Точный внутренний контроль суммы полезен. Но не нужно превращать каждое действие в громкий пересчёт всего банка. Какие суммы и по каким запросам объявляют в конкретном формате игры, определяет регламент.

12. ЕСЛИ РАСЧЁТ НЕ СОШЁЛСЯ

Не добавляйте недостачу из чужого стека и не прячьте лишние фишки в банк. Остановитесь до следующего необратимого действия.

Сохраните раздельные ставки и раскладку. Проверьте номиналы, количество, прежние взносы, сдачу и возвраты. Чётко сообщите, в чём расхождение: например, «для колла до 700 внесено 100 ранее и 500 сейчас, не хватает 100».

Если возник спор или нельзя уверенно восстановить действие, пригласите флора. Задача дилера — сохранить проверяемую ситуацию, а не любой ценой продолжить раздачу.

13. ПРАКТИКА С ТРЕНЕРОМ

Упражнение 1. Номиналы и нарезка.
Разделить 20 одинаковых фишек на четыре группы по пять. Затем повторить с группами по четыре. Тренер проверяет точное количество и устойчивость движений.

Упражнение 2. Смешанная сумма.
Тренер выкладывает несколько номиналов. Ученик разделяет их, объявляет промежуточные суммы и общий результат. После точной проверки можно ускоряться.

Упражнение 3. Добавить до суммы.
Тренер задаёт прежнюю ставку и новую требуемую сумму. Ученик сначала называет разницу, затем выкладывает нужное добавление.

Упражнение 4. Колл и сдача.
Сценарий: прежде внесено 100, требуется 700, добавлена фишка 1 000 после объявления колла. Ученик сохраняет понятную раскладку, оставляет общий вклад 700 и выдаёт 400 сдачи по принятой процедуре.

Упражнение 5. Не перепутать действия.
Одна фишка 1 000 как первая ставка; одна фишка 1 000 молча в ответ на 600; объявленный допустимый рейз до 1 000. Ученик сначала определяет действие и только затем работает с суммой.

Упражнение 6. Закрыть круг.
Несколько ставок, один фолд, один короткий олл-ин. Ученик не смешивает вклады до установления всех сумм и показывает, какую информацию нужно сохранить для расчёта банков.

Норматив скорости устанавливает тренер после отработки точности. Не нужно вводить требование «за одну секунду» там, где ученик ещё путает номиналы или суммы.

Итоговая памятка

Сначала действие, потом сумма. Сначала проверка, потом сдача. Старые улицы не оплачивают новый колл. Анте не заменяет живой BB. Размен сохраняет стоимость. Неуравнённое возвращается. Ставки не смешиваются, пока их ещё нужно проверить.

После блока — отдельный тест на суммы и порядок действий. Работу рук, нарезку и реальную передачу фишек проверяет тренер.',NULL,'[]'::jsonb,'[]'::jsonb,4,true,false,true),
('5f117aad-309e-5a85-bc17-a56bd4cd5f09','0c4b87dc-bb33-5d9d-a787-de0836796c34','Основной банк и сайд-поты: расчёт слоями','Задача блока

Научиться последовательно формировать банки при разных олл-инах, понимать, кто имеет право на каждый банк, и передавать фишки правильным победителям. Здесь важно разделить две задачи: сначала установить состав и участников банков, затем определить победителей по картам.

В учебных расчётах указаны итоговые вклады за обозначенный период, а не дополнительные фишки сверх этих сумм. Если не сказано иначе, анте, ранее сформированного банка, штрафных блайндов и других дополнительных взносов нет. Это позволяет сначала понять основной алгоритм без скрытых условий.

1. ЧТО ТАКОЕ ОСНОВНОЙ И ПОБОЧНЫЙ БАНК

Основной банк, или main pot, — банк первого уровня вкладов. При коротком олл-ине это та часть, на которую может претендовать самый короткий оставшийся участник.

Побочный банк, или side pot, — отдельная часть, образованная дополнительными уравненными вкладами других игроков. Короткий игрок не может выиграть фишки из уровня, который не покрыт его вкладом.

Несколько побочных банков возникают не потому, что на столе много игроков, а потому, что есть несколько разных уровней уравненных вкладов с разным составом претендентов.

Число олл-инов не равно числу побочных банков. Три игрока в олл-ине на одинаковые суммы обычно образуют один общий банк без сайд-пота. Три разных суммы могут образовать несколько банков и возврат неуравнённого остатка.

Важно: право на банк определяется участием и вкладом, а победа в нём — сравнением допустимых рук. Большой стек сам по себе не даёт права выиграть банк.

2. СНАЧАЛА СОХРАНИТЬ ВКЛАДЫ

Не сгребайте разные олл-ины в одну неразличимую кучу. До расчёта должно быть понятно:
— сколько внёс каждый игрок;
— какие суммы относятся к одному и тому же периоду расчёта;
— кто остаётся в раздаче, а кто сбросил карты;
— кто ещё может действовать;
— есть ли уже сформированные банки предыдущих улиц.

Пример: A внёс 300, B — 1 000, C — 1 000. Это итоговые суммы. Нельзя затем прибавить к ним ранее внесённые блайнды ещё раз, если они уже включены в указанные вклады.

Сброс карт не стирает внесённые фишки. Вклад игрока остаётся в банках, но его сброшенная рука больше не претендует на выигрыш.

Проверка перед переходом: вклады сохранены, статусы игроков понятны, суммы не посчитаны дважды.

3. НЕУРАВНЁННЫЙ ОСТАТОК: ВЕРНУТЬ ДО ПЕРЕДАЧИ БАНКОВ

Если только один игрок внёс сумму выше всех остальных, часть выше максимального вклада любого соперника не имеет ответа и возвращается ему. Это не отдельный выигранный банк.

Пример: A — 300, B — 1 000, C — 1 500. Других вкладов нет, все необходимые действия завершены. У C только 1 000 покрыты вкладом B. Лишние 500 возвращаются C.

После возврата для расчёта остаются A — 300, B — 1 000, C — 1 000. Всего в разыгрываемых банках 2 300. Исходно было выдвинуто 2 800: разница 500 — именно возврат.

Не ориентируйтесь только на самого короткого игрока. A внёс 300, но B уравнял C до 1 000. Поэтому C возвращаются 500, а не 1 200.

Если торговля ещё продолжается, окончательный возврат нельзя определять, игнорируя игрока, который ещё должен ответить. Сначала завершите необходимые действия.

Проверка перед переходом: отдельно обозначен возврат; в банках остались только вклады, которые действительно разыгрываются.

4. БАЗОВЫЙ ПРИМЕР: 300 / 1 000 / 1 000

A идёт в олл-ин на 300. B и C вносят по 1 000. Все трое остаются в раздаче, действий больше нет.

Шаг 1. Первый уровень — 300 от каждого из трёх.
300 × 3 = 900. Это основной банк. На него претендуют A, B и C.

Шаг 2. После выделения основного банка у B и C остаётся по 700.
700 + 700 = 1 400. Это побочный банк. На него претендуют только B и C.

Шаг 3. Проверяем общую сумму.
900 + 1 400 = 2 300.
Исходные вклады: 300 + 1 000 + 1 000 = 2 300. Суммы совпадают.

Шаг 4. Отмечаем участников.
Основной: A, B, C.
Побочный: B, C.

A может иметь лучшую руку за столом и выиграть 900, но не может забрать побочные 1 400. Эти фишки разыгрываются между B и C.

5. НЕСКОЛЬКО БАНКОВ: 400 / 900 / 1 500 / 1 500

Четыре игрока остаются в раздаче. A внёс 400, B — 900, C и D — по 1 500. Других взносов нет.

Первый уровень — 400 с каждого из четырёх.
400 × 4 = 1 600. Основной банк: A, B, C, D.

Второй уровень — разница между 900 и 400, то есть ещё 500 с B, C и D.
500 × 3 = 1 500. Побочный банк 1: B, C, D.

Третий уровень — разница между 1 500 и 900, то есть ещё 600 с C и D.
600 × 2 = 1 200. Побочный банк 2: C, D.

Проверка: 1 600 + 1 500 + 1 200 = 4 300.
Исходные вклады: 400 + 900 + 1 500 + 1 500 = 4 300.

Частая ошибка — второй уровень посчитать как 900 × 3. Первые 400 от этих игроков уже вошли в основной банк. На следующем уровне считают разницу, а не весь вклад повторно.

Другая ошибка — добавить A в участники второго банка. У него нет вклада выше 400, значит, на второй уровень он не претендует.

6. УНИВЕРСАЛЬНЫЙ СПОСОБ: СЧИТАТЬ СЛОЯМИ

Для обычных раздельно сохранённых вкладов без специальных взносов удобно использовать слои.

1. Установите итоговые вклады и завершённость действий.
2. Выделите неуравнённый верхний остаток, если он есть.
3. Найдите первый положительный уровень вкладов.
4. Возьмите соответствующую сумму с каждого, кто внёс не меньше этого уровня.
5. Для следующего уровня используйте только прибавку относительно предыдущего.
6. Внутри каждого слоя отдельно отметьте живые руки, имеющие на него право.
7. Сверьте сумму всех банков и возвратов с исходными вкладами.

Фишки сбросившихся игроков участвуют в подсчёте денег, но их руки не участвуют в сравнении. Не путайте число вкладчиков и число претендентов.

Если несколько соседних слоёв имеют одинаковый состав претендентов и нет иных ограничений, они могут относиться к одному банку. Не нужно создавать дополнительный сайд-пот только ради каждой отдельной цифры в расчёте. Физическую раскладку и объединение таких частей отрабатывают с тренером.

Нестандартные обязательные взносы и право на них разбираются по отдельным правилам, а не автоматически этим упрощённым алгоритмом.',NULL,'[]'::jsonb,'[]'::jsonb,0,true,false,true),
('2db6ab7f-0609-5531-883b-cbf4ac661456','0c4b87dc-bb33-5d9d-a787-de0836796c34','Фолд, прежний банк и продолжающаяся торговля','7. ИГРОК СБРОСИЛ КАРТЫ: ФИШКИ ОСТАЛИСЬ

A внёс 400 и находится в олл-ине. B и C внесли по 1 000. D ранее внёс 400 и затем сбросил карты. Все необходимые действия завершены.

Первый уровень: 400 от A, B, C и D.
400 × 4 = 1 600. Претенденты: A, B, C. D не участвует в сравнении, но его 400 остаются здесь.

Следующий уровень: по 600 от B и C.
600 × 2 = 1 200. Претенденты: B и C.

Всего: 1 600 + 1 200 = 2 800.
Исходные вклады: 400 + 1 000 + 1 000 + 400 = 2 800.

Если ошибочно убрать вклад D, из расчёта исчезнут 400. Если оставить D в претендентах, будет ошибочным право на выигрыш. Проверять нужно и сумму, и состав участников.

8. УЖЕ ЕСТЬ БАНК ПРЕДЫДУЩЕЙ УЛИЦЫ

Не считайте весь старый банк как новый вклад каждого игрока. Уже сформированная сумма и новые ставки — разные части расчёта.

Пример: на флоп вышли трое. В центре 900, и все трое имеют право на этот банк. Других банков нет. На флопе A ставит последние 200, B и C в итоге вносят по 600 каждый.

Новый первый уровень — по 200 с троих: 600. Он добавляется к существующему общему банку 900. Основной банк становится 1 500, претенденты A, B и C.

Остаток новых вкладов B и C — по 400. Побочный банк 800, претенденты B и C.

Проверка: старые 900 + новые 200 + 600 + 600 = 2 300.
Новые банки: 1 500 + 800 = 2 300.

Старые 900 не делят произвольно на три новых «стека по 300». Они уже являются банком с установленным составом участников.

Если на предыдущих улицах уже было несколько банков, сохраняйте право на каждый из них. Не объединяйте их только потому, что физически удобнее поставить все фишки рядом.

9. ОДИН ОЛЛ-ИН НЕ ОСТАНАВЛИВАЕТ ТОРГОВЛЮ ОСТАЛЬНЫХ

A в олл-ине, а у B и C ещё есть фишки. Они могут продолжать делать ставки между собой, если по очереди действий и правилам ставок такая торговля возможна. Новые уравненные ставки B и C не расширяют права A.

Дилер не должен автоматически открывать остаток борда, увидев один олл-ин. Сначала проверяется, завершено ли действие и могут ли другие участники продолжать торговлю.

Если B и C больше не могут ставить, необходимое действие завершено и осталось только открыть борд, действуют процедура раскрытия олл-инов и обычная последовательность бёрнов и улиц.

Здесь мы изучаем состав банков. Вопросы минимального повышения и возобновления права на рейз при коротком олл-ине относятся к блоку ставок и объявлений.',NULL,'[]'::jsonb,'[]'::jsonb,1,true,false,true),
('27fc2ffc-c2da-5d5a-9414-a00975d1102a','0c4b87dc-bb33-5d9d-a787-de0836796c34','Победители и порядок передачи банков','10. КАК ОПРЕДЕЛЯТЬ ПОБЕДИТЕЛЕЙ

Каждый банк — отдельная задача сравнения рук.

Сначала установите, кто имеет право на выбранный банк. Затем сравните лучшие пятикарточные руки только этих участников. Не позволяйте самой сильной руке за столом автоматически выиграть банк, на который её владелец не претендует.

Пример 300 / 1 000 / 1 000: основной 900, побочный 1 400. По картам A сильнее B, B сильнее C.

Основной выигрывает A: он имеет на него право и его рука лучшая среди A, B, C.
Побочный выигрывает B: A в нём не участвует, а среди B и C сильнее B.

Другой результат при тех же вкладах: C сильнее A, A сильнее B. Тогда C выигрывает оба банка, потому что имеет право на каждый и оказывается лучшим среди соответствующих участников.

Не выдавайте фишки, пока не проверены все претендующие руки. Не убирайте карты так, чтобы нельзя было проверить уже объявленный результат.

11. ПОРЯДОК ПЕРЕДАЧИ НЕСКОЛЬКИХ БАНКОВ

Проверяйте и передавайте банки последовательно от последнего побочного к основному: сначала банк с самым узким составом претендентов, затем предыдущий, затем основной. Перед каждым перемещением назовите банк, проверьте сумму и победителей. Не смешивайте ещё не распределённые банки.

При вкладах 400 / 900 / 1 500 / 1 500 последовательность проверки может быть такой:
— побочный 2, 1 200: сравнить C и D;
— побочный 1, 1 500: сравнить B, C и D;
— основной, 1 600: сравнить A, B, C и D.

Назовите, какой банк передаёте, проверьте сумму и получателя. Не переносите фишки из следующего банка просто потому, что тот же игрок только что выиграл предыдущий.

Сохраняйте борд и необходимые открытые руки доступными для проверки до завершения расчёта. Как именно убирать уже не претендующие карты, тренер показывает отдельно; главное — не потерять возможность правильно сравнить оставшиеся банки.',NULL,'[]'::jsonb,'[]'::jsonb,2,true,false,true),
('e462f7cf-69f9-527b-bb39-b6d3fb70f553','0c4b87dc-bb33-5d9d-a787-de0836796c34','Деление банка и нечётная фишка','12. ДЕЛЕНИЕ: РАВНЫЕ РУКИ ДЕЛЯТ КОНКРЕТНЫЙ БАНК

Равенство означает одинаковую лучшую пятикарточную комбинацию. Совпадение названия «пара» или «стрит» само по себе не гарантирует равенства: учитываются достоинства карт и необходимые кикеры.

Если два равноправных победителя делят банк 1 600, каждому приходится по 800. Если трое делят 2 100 — по 700. Для этих примеров предполагается, что доступные номиналы позволяют выдать указанные суммы.

При нескольких банках равенство проверяется отдельно в каждом.

Пример: A, B и C внесли 300 / 1 000 / 1 000. A и B имеют одинаковую лучшую руку, C слабее.
Основной 900 делится между A и B: по 450 при доступном номинале 50.
Побочный 1 400 получает B полностью: в нём сравниваются только B и C.
Итого A получает 450, B — 1 850, C — 0. Общая выплата 2 300.

Не делите побочный банк с A только потому, что он разделил основной. У каждого банка свой список участников.

13. НЕЧЁТНАЯ ФИШКА

Перед делением используйте минимальный номинал фишек, который остаётся в игре. Если банк всё равно не делится поровну, равные доли выдаются каждому победителю, а нечётная фишка достаётся первому из победителей этого банка слева от баттона по часовой стрелке.

Считают только претендующих победителей: ближайший к баттону игрок, который проиграл, сбросил карты или вообще не участвует в банке, остаток не получает.

Пример: банк 1 525 делят двое, минимальный номинал — 25. Сначала каждому выделяют по 750, остаётся одна фишка 25. Баттон на месте 1, победители на местах 4 и 7, нумерация идёт по часовой стрелке. Первым слева от баттона расположен победитель на месте 4: он получает 775, победитель на месте 7 — 750.

Не определяйте получателя по силе масти, размеру стека, очередности показа или личному выбору дилера. Нечётную фишку определяют для каждого делимого банка отдельно. Нельзя компенсировать её из другого банка с иным составом участников.',NULL,'[]'::jsonb,'[]'::jsonb,3,true,false,true),
('00a87269-cf48-5ad2-ac8d-a0a8eaf53fb8','0c4b87dc-bb33-5d9d-a787-de0836796c34','Анте, короткий стек и контроль расчёта','14. АНТЕ И КОРОТКИЙ СТЕК

В СПЛ BB-анте равно одному BB, оплачивается раньше живого блайнда, в хедз-апе анте нет. Анте входит в банк и не является доходом клуба или частью живой ставки BB. Уже сформированный банк с анте учитывают один раз.

Если стек BB не покрывает полные обязательные взносы, сначала направьте фишки в анте, затем остаток в живой BB. Сохраните назначения этих фишек и все вклады соперников различимыми.

Перед формированием и передачей спорного банка пригласите флора для определения права короткого игрока на суммы банка. Не рассчитывайте это право автоматически из факта «анте оплачено первым» и не разбивайте BB-анте на вымышленные индивидуальные взносы всех участников.

Числовые упражнения этого блока не рассматривают неполную оплату BB-анте. В остальных примерах отдельно указаны исходные вклады и уже сформированные банки.

15. ДВЕ ОБЯЗАТЕЛЬНЫЕ ПРОВЕРКИ

Первая — деньги.
Все исходные вклады и ранее сформированные банки должны совпасть с суммой итоговых банков и возвратов. После передачи сумма всех выплат и возвратов должна дать ту же общую сумму.

Вторая — право.
На каждый банк претендуют только допустимые участники. Сброшенная рука не выигрывает. Короткий игрок не выигрывает непокрытый им побочный уровень. Лучшие пять карт сравниваются отдельно внутри каждого банка.

Правильная сумма при неверных получателях — всё равно ошибка. Верные получатели при потерянных фишках — тоже ошибка.

Если расчёт не сходится, остановите передачу, сохраните отдельные банки и открытые руки, проверьте вклады, уровни и возврат. При споре пригласите флора. Не начинайте следующую раздачу до завершения расчёта.

16. ПРАКТИКА С ТРЕНЕРОМ

Первый этап: без карт разложить банки 300 / 1 000 / 1 000. Назвать суммы и претендентов.

Второй: разложить 400 / 900 / 1 500 / 1 500. Не считать одинаковые части повторно.

Третий: добавить сбросившегося вкладчика. Сохранить его фишки, исключить руку из претендентов.

Четвёртый: добавить неуравнённый верхний остаток. Отделить возврат от банков.

Пятый: использовать готовый общий банк предыдущей улицы и новые разные ставки.

Шестой: открыть руки, чтобы разные банки выиграли разные игроки. Затем повторить с делением основного банка и единственным победителем побочного.

Сначала ученик вслух объясняет каждый шаг. Затем выполняет ту же процедуру самостоятельно. Скорость увеличивается только после стабильного совпадения сумм и правильного определения прав.

Итоговая памятка

Сохранить вклады → завершить действие → вернуть неуравнённое → выделить уровни → отметить претендентов → сверить суммы → сравнить руки по каждому банку → разделить при равенстве → применить правило нечётной фишки при необходимости → передать и проверить выплаты.

После блока — тест на расчёты и право участия. Реальную раскладку, технику передачи банков и сложные игровые ситуации проверяет тренер.',NULL,'[]'::jsonb,'[]'::jsonb,4,true,false,true),
('0f9886b6-f21e-5a1d-9df1-d5fcbe92237b','1dacf3d8-b5af-54ca-9763-e8f400bd7dfe','Уровни, гонг и обязательные ставки','Уровни, баттон, хедз-ап, новые игроки, пересадки и укрупнение фишек

Задача блока

Научиться правильно подготовить следующую раздачу, когда за столом что-то изменилось. В обычной раздаче позиции и суммы знакомы. После повышения уровня, выбывания или пересадки нельзя продолжать механически: сначала нужно проверить новые условия.

Главная последовательность

Завершить текущую раздачу → установить, что изменилось → проверить уровень и состав стола → определить баттон и обязательные ставки → проверить допуск новых участников → подготовить колоду → начать следующую раздачу.

Решения о пересадках, остановке столов, санкциях и специальных процедурах принимает уполномоченный персонал турнира. Дилер исполняет процедуру и сохраняет контроль стола, а не меняет структуру турнира по своему усмотрению.

Основные правила СПЛ

Анте: размер — один BB, платит BB, сначала анте, затем живой BB, в хедз-апе анте нет.

Смена уровня: сигнал — гонг таймера. Если до гонга выставлен хотя бы один из блайндов, эта раздача проводится по старому уровню, следующая — по новому. Если ни SB, ни BB ещё не выставлены, применяется новый уровень.

Балансировка: минимальный рабочий состав стола — шесть игроков. Если участников становится меньше, требуется балансировка при возможности пересадки. До начала раздачи для перемещения выбирают UTG; если выбор делают во время раздачи — игрока непосредственно после UTG, то есть UTG+1. На новом столе стараются сохранить прежнюю позицию.

Вывод номиналов и укрупнение: в запланированные перерывы по структуре турнира. Не образующие точной обменной суммы остатки округляются вверх. В описанной процедуре СПЛ остатки не разыгрываются картами.

В СПЛ применяется мёртвый баттон. После выбываний сохраняют правильное движение обязательных блайндов; кнопка может оказаться у пустого места. При нескольких свободных местах её можно продвинуть дальше по пустым позициям для допуска новых участников, если это сохраняет нормальное движение блайндов и не приводит к пропуску или повторному BB. Сложную расстановку устанавливают до начала следующей раздачи, при споре — с флором.

1. КАК ЧИТАТЬ УРОВЕНЬ

Уровень задаёт размер малого и большого блайндов, а по структуре турнира — и анте. Не определяйте сумму по памяти о предыдущей раздаче: проверяйте актуальную структуру и указания персонала.

Пример СПЛ: уровень 100/200 означает SB 100, BB 200 и BB-анте 200 при трёх и более игроках за столом. Игрок BB обычно вносит всего 400: сначала 200 анте, затем 200 живого BB.

На уровне 200/400 обычный взнос BB при трёх и более игроках — 400 анте плюс 400 BB, всего 800. Малый блайнд — 200.

Это не означает, что соперникам нужно уравнивать 800: живая ставка BB равна 400. Анте уже относится к банку.

В хедз-апе на том же уровне 200/400: BTN/SB — 200, BB — 400, анте нет. Обычная сумма обязательных ставок до добровольных действий — 600.

Уровни не обязаны идти простым удвоением. После 100/200 следующий уровень может быть иным: его определяет структура, а не арифметическая догадка дилера.

2. СМЕНА УРОВНЯ: ГОНГ И ВЫСТАВЛЕННЫЕ БЛАЙНДЫ

В СПЛ уровень повышается по таймеру со звуком гонга. Для определения уровня ближайшей раздачи проверяют, были ли до гонга выставлены блайнды.

Если выставлен хотя бы один — SB или BB, — эта раздача идёт по старому уровню. Второй блайнд также выставляется по старому уровню. Следующую раздачу проводят уже по новому.

Если ни SB, ни BB ещё не выставлены, после гонга оба ставятся по новому уровню. Сам факт подготовки или тасовки колоды не заменяет эту проверку.

Пример 1. Был уровень 100/200. SB уже поставил 100, BB ещё не выставлен. Звучит гонг перехода на 200/400. Эта раздача остаётся на 100/200: BB ставит 200 живого блайнда и, при трёх и более игроках, 200 анте. Следующая раздача — на 200/400.

Пример 2. При том же переходе никто ещё не выставил ни SB, ни BB. После гонга SB ставит 200, BB — 400 живого блайнда и 400 анте при трёх и более игроках. Уже эта раздача проводится по новому уровню.

Порядок действий:
1. Услышать гонг и проверить новый уровень по структуре.
2. Установить, был ли до гонга выставлен хотя бы один блайнд.
3. Если да — завершить данную раздачу на старом уровне; если нет — применить новый.
4. Объявить суммы и проверить SB, живой BB и соответствующее анте.
5. Если оставались на старом уровне, перед следующей раздачей обязательно перейти на новый.

Не меняйте обязательные ставки уже идущей раздачи посередине торговли и не требуйте доплаты только потому, что прозвучал гонг. Не забывайте, что в хедз-апе СПЛ анте нет независимо от уровня.',NULL,'[]'::jsonb,'[]'::jsonb,0,true,false,true),
('a8bd92be-f3bf-560b-926d-2cd6e171a5e4','1dacf3d8-b5af-54ca-9763-e8f400bd7dfe','Движение баттона после выбывания','3. БАТТОН — ЭТО ПОЗИЦИЯ, А НЕ НАГРАДА ИГРОКУ

Баттон помогает определить позиции и порядок действий. Его движение связано с обязательными ставками, а не с тем, кто выиграл банк или кому «давно не было удобно».

На полном столе без выбываний позиции обычно сдвигаются по часовой стрелке: прежний BB становится SB, прежний SB получает баттон, следующий игрок принимает BB. При выбывании схема может включать пустую позицию и отсутствие SB.

Не двигайте все обозначения сразу на ближайших сидящих людей, не проверив последствия. Так можно заставить игрока пропустить положенный BB или получить его повторно неправильно.

Для проверки сохраняйте картину предыдущей раздачи: где были BTN, SB и BB; кто выбыл; какие места заняты к следующей раздаче. Без предыдущих позиций легко получить красивую, но неверную новую схему.

4. ЗАЧЕМ НУЖЕН МЁРТВЫЙ БАТТОН

Мёртвый баттон — положение кнопки у места, которому в следующей раздаче не соответствует участвующий игрок. Это не ошибка оборудования и не разрешение сдавать карты пустому месту.

При использовании мёртвого баттона цель — сохранить правильное движение обязательных блайндов после выбываний. Иногда для этого кнопка остаётся у пустого места. Очередь на постфлопе всё равно определяется относительно позиции баттона, но пустые места и не действующие руки пропускаются.

Не путайте мёртвый баттон с мёртвой рукой. Баттон — позиция. Мёртвая рука — статус карт конкретного участника по правилам.

Пример 1. Выбыл прежний SB.

Места идут по часовой стрелке: 1, 2, 3, 4, 5, 6. В предыдущей раздаче BTN был на месте 1, SB на 2, BB на 3. Игрок места 2 выбыл, остальные остаются.

При использовании мёртвого баттона следующая схема: BTN у пустого места 2, SB на месте 3, BB на месте 4. Пустому месту 2 карты не сдают.

Зачем так: прежний BB на месте 3 переходит на SB, следующий игрок на месте 4 принимает BB. Если просто перескочить кнопкой к месту 3 и затем расставить SB на 4, BB на 5, место 4 пропустит ожидаемый BB.

На схеме сначала найдите прошлые позиции, затем исключите выбывшее место 2 и установите новые положения кнопки и блайндов.

5. ПОЧЕМУ ИНОГДА НЕТ МАЛОГО БЛАЙНДА

При использовании мёртвого баттона после некоторых выбываний следующая раздача проводится без SB. Это не означает автоматического отсутствия BB.

Пример 2. Выбыл прежний BB.

На тех же местах в предыдущей раздаче BTN — 1, SB — 2, BB — 3. Теперь выбыл игрок места 3, остальные остаются.

Следующая схема: BTN — место 2, позиция SB приходится на пустое место 3, BB — место 4. За пустое место никто не платит. Не нужно автоматически сдвигать SB к месту 4, а BB к месту 5.

В СПЛ действующий BB на месте 4 при трёх и более игроках оплачивает своё BB-анте и живой BB. Отсутствие SB не превращает анте в дополнительный малый блайнд.

Если одновременно выбыли несколько игроков или выполняется пересадка, сначала восстановите предыдущие позиции и установите следующего BB. Не перемещайте все обозначения механически к ближайшим занятым стульям. При споре сохраните прошлую схему и пригласите флора до начала новой раздачи.',NULL,'[]'::jsonb,'[]'::jsonb,1,true,false,true),
('6220c688-71f4-5f89-97d2-27ee8a280a71','1dacf3d8-b5af-54ca-9763-e8f400bd7dfe','Переход в хедз-ап','6. ПЕРЕХОД В ХЕДЗ-АП

Хедз-ап здесь — два оставшихся участника за столом, а не два игрока, дошедших до флопа за большим столом. Если из шести человек четверо сбросили карты, режим анте не меняется посреди раздачи.

Когда за столом действительно остаются двое, до следующей раздачи проверьте позиции по правилу перехода в хедз-ап. Нельзя просто оставить прежние BTN, SB и BB как три независимые позиции.

В хедз-апе:
— баттон одновременно является SB;
— другой игрок ставит BB;
— первую карманную карту получает BB;
— первым на префлопе действует BTN/SB;
— первым после флопа действует BB, если он ещё может действовать;
— в СПЛ анте нет.

При переходе в хедз-ап сначала назначьте BB с учётом предыдущей раздачи: игрок не должен получить BB два раза подряд из-за переходной расстановки. Второй участник становится BTN/SB. Если для этого нужно изменить положение кнопки, сделайте это до следующей сдачи. Баттон случайным образом заново не разыгрывают.

Пример обычного уже установленного хедз-апа на 200/400: BTN/SB вносит 200, BB — 400. Карты: сначала BB, затем BTN/SB, затем снова BB и BTN/SB. Первое решение префлопа принадлежит BTN/SB. Без повышений для колла ему нужно добавить 200.',NULL,'[]'::jsonb,'[]'::jsonb,2,true,false,true),
('62521b2f-ae55-56ab-99fe-34c758894254','1dacf3d8-b5af-54ca-9763-e8f400bd7dfe','Посадка, балансировка и расформирование','7. НОВЫЙ ИГРОК ЗА СТОЛОМ

Не начинайте с вопроса «есть ли свободный стул». Сначала нужно установить право игрока занять конкретное место и войти в игру именно сейчас.

Посадка при регистрации, повторном входе и расформировании отличается от балансировки. При регистрации, позднем входе и повторном входе участнику выдаётся полный стартовый стек и случайно назначается стол и место из действующего пула посадки. Он может получить любую позицию, включая SB, BB или баттон, но не вступает в раздачу, если находится между SB и баттоном. Карты не досдают в уже начатую сдачу.

Порядок действий дилера:
1. Проверить назначенный стол и место по принятому способу подтверждения.
2. Установить причину посадки и при необходимости получить указание флора.
3. Проверить, завершена ли уже идущая раздача и разрешено ли участие в ближайшей.
4. Определить позиции и обязательные взносы по регламенту входа.
5. Убедиться, что фишки нового игрока не смешаны с чужим стеком.
6. Только после допуска включить участника в порядок сдачи.

Игрок, подошедший после начала сдачи, не должен получать две карты из остатка колоды только потому, что успел сесть до флопа. Допуск к уже начатой раздаче и обязанность присутствия регулируются правилами, а не удобством.

Не назначайте входной «штрафной блайнд» по аналогии с кеш-игрой. Перед сдачей проверьте право на участие и позицию: для новых игроков и переведённых с расформированного стола исключение — положение между SB и баттоном. После назначения места игрок выполняет обязательные ставки своей позиции.

8. БАЛАНСИРОВКА СТОЛОВ

Балансировка — перемещение игроков между продолжающими работать столами, чтобы выровнять состав. В СПЛ минимальный рабочий состав стола — шесть человек. Если остаётся пять или меньше, нужно сообщить флору и организовать балансировку при наличии подходящего стола-донора. Это правило не запрещает финальный стол или предусмотренный переход в хедз-ап: когда пересаживать некого, дальнейший формат определяет персонал турнира.

Выбор игрока зависит от момента, когда его определяют для пересадки:
— если следующая раздача ещё не началась — берут UTG;
— если выбор происходит во время раздачи — берут игрока сразу после UTG по порядку позиций этой раздачи, то есть UTG+1.

Не путайте UTG+1 с игроком, который только что отыграл BB. Сначала определите реальные позиции и стадию игры, затем назовите нужного участника.

Пример: в текущей раздаче A — UTG, B — следующий за ним UTG+1. Если игрока выбирают во время этой раздачи, для пересадки выбирают B. Это не разрешение забрать его карты или стек посреди незавершённого действия: момент фактического перехода согласуют с флором после завершения применимой раздачи.

На новом столе стараются посадить игрока на ту же позицию, с которой он переводится. «Стараются» не означает произвольное занятие чужого места: конкретное назначение и решение при отсутствии подходящей позиции подтверждает флор.

До отправки игрока:
1. Подтвердите необходимость балансировки и назначение у флора.
2. Установите момент выбора и определите UTG либо UTG+1 по правилу выше.
3. Завершите применимую раздачу, не изымая участвующий стек и живую руку посреди игры.
4. Подтвердите новый стол, место и позицию.
5. Сохраните правильное движение баттона и блайндов на исходном столе и контролируемый перенос стека.

На принимающем столе подтвердите место и момент вступления в игру. Не назначайте повторный взнос и не освобождайте от него по своему усмотрению. Если точное сохранение позиции невозможно или неясен момент допуска, решение подтверждает флор.

9. РАСФОРМИРОВАНИЕ СТОЛА

При расформировании исходный стол прекращает работу, а его участники получают другие места. Это отличается от перемещения одного игрока при балансировке.

После команды флора не начинайте дополнительную раздачу только ради того, чтобы «успеть ещё одну». Уточните, какую раздачу необходимо завершить, и остановитесь в указанный момент.

Подтвердите новые назначения игроков, обеспечьте различимость стеков и контролируемый перенос фишек. Если используются специальные рэки или боксы, действуйте по этой процедуре. Не допускайте бесконтрольного смешения фишек разных игроков.

При расформировании новые столы и места назначаются случайно в два этапа: сначала стол, затем место. Игрок не меняет назначение самостоятельно. На новом столе он может вступить в игру на любой позиции, включая SB, BB или баттон, кроме положения между SB и баттоном. Это не правило балансировки UTG/UTG+1: при балансировке сохраняется описанный выше порядок СПЛ.

За сокрытие фишек или нарушение переноса дилер сообщает флору. Конкретную санкцию не назначает самостоятельно.',NULL,'[]'::jsonb,'[]'::jsonb,3,true,false,true),
('5d566d2b-fc99-58d5-b58a-e74dc54dfb35','1dacf3d8-b5af-54ca-9763-e8f400bd7dfe','Перерывы, вывод номиналов и округление','10. ПЕРЕРЫВ И СПЕЦИАЛЬНАЯ ОСТАНОВКА

Сигнал перерыва не разрешает бросить незавершённую раздачу, забрать живые карты или передать банк без результата. Порядок завершения текущей раздачи и прекращения новых определяет регламент и указание персонала.

После завершения действий сохраните стеки и игровое оборудование по процедуре клуба. Не оставляйте незавершённый размен, невыданную сдачу или спорный банк «до возвращения».

Отдельная команда остановить игру для балансировки, синхронной игры по раздачам или другой процедуры также обязательна. Не запускайте новую раздачу самостоятельно, пока остановка не снята.

При возобновлении проверьте: новый уровень, количество участников, позиции, состояние стеков и завершение всех технических процедур. Только затем переходите к обычной подготовке раздачи.

11. ВЫВОД НОМИНАЛОВ, УКРУПНЕНИЕ И ОКРУГЛЕНИЕ

В СПЛ мелкие номиналы выводят в заранее предусмотренные перерывы. Моменты определяются структурой турнира. Например, на предусмотренном структурой этапе при переходе с BB 2 000 к BB 3 000 выводятся сотенные фишки. Самостоятельно начинать вывод при любом похожем уровне нельзя: сначала проверяют план турнира.

Одновременно выполняется укрупнение: несколько мелких фишек заменяют эквивалентной суммой крупных. Десять фишек по 100 дают 1 000 и могут быть заменены одной фишкой 1 000. В точном обмене стоимость сохраняется.

Остатки в СПЛ округляются вверх до ближайшей суммы, которую можно выдать оставшимися игровыми номиналами. Это правило СПЛ. Карты для розыгрыша остатков при этой процедуре не раздают.

Пример при выводе сотен, если минимальный оставшийся номинал — 500:
— 300 заменяются на 500;
— 500 заменяются на 500 без прибавки;
— 700 заменяются на 1 000;
— 1 200 заменяются на 1 500.

Округляют общую обмениваемую сумму игрока, а не каждую сотенную фишку отдельно. Три фишки по 100 — это 300, которые округляются до 500, а не три отдельные выдачи по 500.

При округлении сумма стека может увеличиться на величину округления. Не нужно объявлять такой результат ошибкой сохранения стоимости: точный обмен и разрешённое округление — разные операции. Но произвольной дополнительной прибавки сверх правила быть не должно.

Порядок действий:
1. Получить подтверждение начала плановой процедуры в перерыве.
2. Проверить выводимый номинал и остающиеся номиналы.
3. Сохранить принадлежность фишек каждому игроку, не смешивать остатки разных стеков.
4. Подсчитать общую сумму выводимых фишек каждого игрока.
5. Выполнить точную замену там, где она возможна; при остатке округлить общую сумму вверх по правилу.
6. Проверить выданную сумму, затем убрать заменённые фишки из игры по принятой процедуре.
7. После завершения проверить стеки и разрешение возобновить игру.

При выводе номиналов показывайте последовательность: подсчёт общей суммы мелких фишек игрока, обмен, округление остатка вверх и контроль результата. Остатки картами не разыгрываются.',NULL,'[]'::jsonb,'[]'::jsonb,4,true,false,true),
('30466f77-1a01-5e0a-83df-6372dead2ed0','1dacf3d8-b5af-54ca-9763-e8f400bd7dfe','Отсутствие, штраф и полномочия дилера','12. ОТСУТСТВУЮЩИЙ ИГРОК И ШТРАФ

Свободное место после выбывания и место временно отсутствующего зарегистрированного участника — разные ситуации. Не подсаживайте нового игрока на место отошедшего человека без назначения персонала.

Для живой руки участник должен находиться в пределах досягаемости своего стула к моменту окончания исходной сдачи последней карты всем. Если его нет, смотреть свои карты он не может, рука немедленно гасится. Блайнды и анте остаются в банке. Появление до первого собственного действия не оживляет уже погашенную руку.

С живой рукой, включая олл-ин, участник остаётся у стола до завершения торговли и вскрытия и защищает свои карты.

Штраф назначает флор. На штрафе игрок находится вне стола, карты на его место сдаются, обязательные взносы выставляются, рука гасится после исходной сдачи. Дилер исполняет назначенный срок, не сокращает и не увеличивает его сам. При пересдаче исходная сдача и повтор считаются одной раздачей для отсчёта штрафа.

13. ЧТО ДИЛЕР ОБЪЯВЛЯЕТ И ЧЕГО НЕ РЕШАЕТ САМ

Полезное объявление короткое и проверяемое: «Новый уровень — 200/400, анте 400 с BB»; «Хедз-ап, без анте»; «Ожидаем подтверждения места»; «Флор, требуется проверить позиции после выбывания».

Не объявляйте универсальное решение, если ещё не проверены условия: «любой новый сразу играет», «малый блайнд всегда обязан быть», «пустой стул всегда пропускаем кнопкой», «любое повышение уровня меняет уже идущую раздачу».

Если сомневаетесь, сохраните предыдущие позиции, обозначьте проблему и не начинайте раздачу с заведомо спорными условиями. Короткая проверка до сдачи безопаснее исправления после появления живых рук.

14. ПРАКТИКА С ТРЕНЕРОМ

Упражнение 1. Уровни.
По карточке структуры назвать SB, живой BB и BB-анте. Затем повторить для хедз-апа. Не считать анте частью суммы колла.

Упражнение 2. Смена уровня.
Тренер подаёт гонг в трёх случаях: ни один блайнд не выставлен; выставлен только SB; выставлены оба. Ученик выбирает уровень по правилу СПЛ: без выставленных блайндов — новый, при хотя бы одном — старый на эту раздачу и новый на следующую.

Упражнение 3. Позиции на схеме.
Расставить шесть мест, BTN/SB/BB. Убрать прежний SB, затем отдельно прежний BB. Для каждого случая показать прошлые позиции, изменение и следующую схему по описанному порядку.

Упражнение 4. Хедз-ап.
После перехода правильно определить позиции. На уже установленной схеме назвать порядок сдачи, первый ход префлопа, первый ход постфлопа и отсутствие анте.

Упражнение 5. Вход и пересадка.
Получить карточки «новая регистрация», «балансировка», «расформирование». Для балансировки отдельно показать выбор UTG до начала раздачи и UTG+1 во время раздачи; назвать желаемую позицию на принимающем столе. Не переносить это правило автоматически на новую регистрацию и расформирование.

Упражнение 6. Замена номиналов.
В плановом перерыве подсчитать выводимые сотни. При минимальном остающемся номинале 500 заменить суммы 300, 500, 700 и 1 200 на 500, 500, 1 000 и 1 500 соответственно. Округлять общую сумму игрока, а не каждую фишку.

Тест после блока проверяет понятные суммы, различия процедур и стандартные схемы с явно указанными условиями. Ответы теста соответствуют правилам, изложенным в блоке.

Итоговая памятка

Изменились условия → не действовать механически → проверить уровень, участников и позиции → подтвердить вход или перемещение → выполнить специальную процедуру → получить разрешение на возобновление → начать новую раздачу.',NULL,'[]'::jsonb,'[]'::jsonb,5,true,false,true),
('9a095528-17a7-5080-b254-0d5264ef7b23','37bc81e8-0868-5e56-8b0a-395ba7c266c1','Остановка игры, существенные действия и пересдача','Задача блока

Научиться замечать ошибку, не усугублять её следующими действиями и выполнять правильную процедуру исправления. Задача не в том, чтобы любой ценой сохранить первоначальный порядок карт или быстрее продолжить сдачу. Нужно сохранить справедливую, проверяемую игру.

В этом блоке изучается порядок исправления ошибок в СПЛ. Правила обязательных ставок, смены уровня и пересадок действуют совместно с порядком исправления: одна ошибка не разрешает произвольно менять другие условия раздачи.

Основание пересдачи и техническое исправление ранней улицы — разные вопросы. Сначала установите вид ошибки и уже совершённые действия. При сочетании нескольких ошибок окончательное решение принимает флор с учётом всех обстоятельств.

Главная последовательность

Заметить ошибку → остановить дальнейшую сдачу и передачу банка → сохранить колоду, борд, бёрны, руки и ставки раздельными → установить, что произошло и какие действия уже были → вызвать флора → выполнить соответствующее исправление → проверить состояние стола → продолжить по разрешению.

Самостоятельная быстрая перетасовка до установления обстоятельств может уничтожить информацию, необходимую для верного решения.

1. ЧТО НУЖНО СООБЩИТЬ ФЛОРУ

Коротко и по фактам: какая улица; какая ошибка; какие карты и зоны затронуты; кто успел действовать и в каком порядке; какие фишки внесены; сохранилась ли уверенная идентификация карт.

Пример: «На флопе не было бёрна. Открыты три карты. Первый игрок уже объявил чек, остальных действий не было». Это полезнее, чем «Я немного неправильно открыл флоп».

Не подсказывайте игроку выгодное решение и не скрывайте собственную ошибку. Сохранить доверие помогает точное описание, а не попытка незаметно заменить карту.

2. СУЩЕСТВЕННЫЕ ДЕЙСТВИЯ: НЕ ПРОСТО “КТО-ТО УЖЕ СХОДИЛ”

Существенные действия (substantial action), или SA, двумя способами:
А. Два действия по очереди, хотя бы одно из которых вносит фишки в банк.
Б. Любые три действия по очереди: чек, ставка, повышение, колл или фолд.

Примеры SA:
— бет, затем колл;
— фолд, затем колл;
— чек, затем бет;
— чек, чек, чек;
— фолд, фолд, фолд.

Не являются SA сами по себе:
— один чек;
— два чека;
— два фолда;
— выставленные SB и BB без последующих нужных действий.

Блайнды не включаются в число SA. Действия должны соответствовать условиям правила, в частности очередности. Не подменяйте его формулой «два любых движения игроков».

SA важны для возможности объявить пересдачу. Но некоторые конкретные исправления имеют другую границу. При флопе без бёрна достаточно одного чека, чтобы оставить исходные три карты. Один чек при этом не превращается в SA для всех других правил.

3. КОГДА ВОЗНИКАЕТ ОСНОВАНИЕ ДЛЯ ПЕРЕСДАЧИ

Основания для пересдачи:
— первая карта выдана не тому месту;
— карты получили на месте, не имеющем права на руку;
— имеющий право участник пропущен;
— игрок получил неверное количество карт, с исключением для баттона с недостающими картами;
— по ошибке дилера открылась одна из первых двух выданных из колоды карт;
— либо открылись две другие карманные карты;
— в исходной сдаче обнаружены две или более boxed cards, то есть перевёрнутые относительно остальной колоды карты.

Список оснований не исчерпывающий. Одиночную boxed card и карту, открытую движением дилера, не нужно автоматически считать одним и тем же случаем: обстоятельства устанавливает флор.

Ключевая граница: после SA обычную пересдачу уже не объявляют, кроме отдельной ситуации fouled deck — дефектной по составу колоды. Ошибочная сдача и дефектная колода не равнозначны.

Поэтому вопрос «это основание для пересдачи?» всегда дополняют вопросом «что уже успели сделать игроки?».',NULL,'[]'::jsonb,'[]'::jsonb,0,true,false,true),
('3aabe88c-0e63-584e-9dee-af795afb39e7','37bc81e8-0868-5e56-8b0a-395ba7c266c1','Открытая карта при сдаче и порядок пересдачи','4. ОТКРЫЛАСЬ КАРТА ПРИ СДАЧЕ

Разберите три разных случая.

Случай А. По ошибке дилера открылась первая или вторая карта всей сдачи.
До SA это основание для пересдачи по правилам СПЛ. Речь о порядковом номере карты из колоды, а не о любой карте, полученной игроком SB или BB. Особенно важно не переносить многоместную расстановку автоматически на хедз-ап.

Случай Б. После первых двух открылась одна карманная карта.
Одна такая карта сама по себе не является основанием для пересдачи. Не прячьте её обратно и не отдавайте игроку решение «оставить или заменить по желанию».

Покажите открытую карту всем, сохраните её отдельно и завершите обычную сдачу. После этого выдайте пострадавшему игроку замену следующей картой из остатка колоды. Открытая карта используется как бёрн перед флопом: дополнительный бёрн перед флопом не делают. До передачи замены сохраняйте правильную последовательность обычной сдачи.

Случай В. По ошибке дилера открылись две карманные карты, не подпадающие уже под случай первых двух.
До SA это основание для пересдачи. После SA нельзя автоматически собрать все руки и начать заново: требуется решение по сохранённым обстоятельствам.

Открытие игроком собственных карт при незавершённой торговле — другая ситуация, а не автоматическое основание пересдавать стол.

5. ЕСЛИ ОБЪЯВЛЕНА ПЕРЕСДАЧА

Пересдача — повтор исходной раздачи, а не новая раздача с новыми условиями.

Баттон не передвигают. Уровень сохраняют. Новых участников между исходной сдачей и её повтором не подсаживают.

Карты получают участники исходной сдачи. В СПЛ допускается участие в повторе игрока, который был включён в исходную сдачу, но отсутствовал на месте при ней. Участникам на штрафе карты выдают и затем гасят руки по правилам штрафа. Исходная сдача и её повтор считаются одной раздачей для отсчёта такого штрафа.

После решения о пересдаче собирайте карты и подготавливайте колоду контролируемо. Не пытайтесь “раздать назад” по памяти уже перемешанные карты. Перед повторной сдачей снова проверьте состав и позиции, но не сдвигайте их как после завершённой нормальной раздачи.',NULL,'[]'::jsonb,'[]'::jsonb,1,true,false,true),
('5e6130ee-da7e-54b9-b810-2af06cdc5cac','37bc81e8-0868-5e56-8b0a-395ba7c266c1','Неверное количество карманных карт','6. У ИГРОКА ОДНА ИЛИ ТРИ КАРТЫ

Если ошибку заметили до SA, это основание для пересдачи, кроме предусмотренных исключений. Одно важное исключение касается баттона с недостающими картами.

Если SA уже произошли, обычную пересдачу всего стола не объявляют. Например, если у игрока не на баттоне после фолда UTG и колла следующего игрока обнаруживается одна или три карты: соответствующая рука мертва, остальные продолжают игру.

Все карты такой мёртвой руки отправляют в мак. Нельзя из трёх карт разрешить выбрать лучшие две. Нельзя третью карту этой руки автоматически сделать бёрном, чтобы “вернуть первоначальный порядок”. Перед следующей улицей выполняется обычный один бёрн из остатка колоды.

До решения флора не смешивайте спорную руку с маком. Сначала устанавливаются факт ошибки и применимое правило, затем выполняется решение.

7. ИСКЛЮЧЕНИЕ: БАТТОН ПОЛУЧИЛ МЕНЬШЕ КАРТ

Игрок на баттоне должен немедленно сообщить о недостающей карте. Недостающие карты могут быть выданы даже после SA, если это допускает вид игры.

Но если баттон уже действует с неполной рукой — например, чекает или делает ставку, — его рука мертва по этому правилу.

Важно для дилера: “после SA у кого угодно одна карта — всегда немедленно пас” не является точным правилом. Проверьте позицию, действия самого игрока и условия исключения. Не досдавайте карту каждому автоматически.',NULL,'[]'::jsonb,'[]'::jsonb,2,true,false,true),
('7e4dc214-78ba-5019-8db7-74a1ec54d00d','37bc81e8-0868-5e56-8b0a-395ba7c266c1','Забытый бёрн: до и после действия','8. ФЛОП БЕЗ БЁРНА, ДЕЙСТВИЙ ЕЩЁ НЕ БЫЛО

Рассмотрим три карты флопа, перед которыми не был сделан бёрн. Неважно, были они уже открыты или ещё нет, и можно ли предположить, какая из них первоначально шла первой.

Порядок:
1. Остановить дальнейшую игру и сообщить ошибку флору.
2. Установить, что после выкладывания флопа ещё не было ни одного действия.
3. Перемешать эти три карты закрыто.
4. Случайно выбрать одну из них как бёрн.
5. Две оставшиеся оставить картами исправленного флопа.
6. Добавить к ним следующую карту из остатка колоды.
7. Только после исправления начать торговлю на флопе.

Здесь не нужно возвращать все три карты в остаток колоды и перетасовывать всю колоду. Это не процедура преждевременного флопа. Также не нужно просто на глаз убрать “первую из трёх”: правило требует случайного выбора после закрытого перемешивания.

9. ФЛОП БЕЗ БЁРНА, НО УЖЕ БЫЛ ОДИН ЧЕК

Если на таком флопе было любое действие, включая один чек, игра продолжается с первоначальными тремя картами флопа.

Нельзя менять одну из них задним числом. Перед тёрном сжигают обычную одну карту. Дополнительный бёрн “за пропущенный” не добавляют.

Сравнение двух случаев:
Нет ни одного действия → исправляем состав флопа по процедуре.
Есть хотя бы один чек → оставляем исходный флоп.

Это специальная граница данного правила. Два чека не нужны, SA не нужны.',NULL,'[]'::jsonb,'[]'::jsonb,3,true,false,true),
('e97a1801-565e-5c89-aa54-db52fe0becbc','37bc81e8-0868-5e56-8b0a-395ba7c266c1','Четыре карты на флопе','10. НА ФЛОПЕ ЧЕТЫРЕ КАРТЫ ВМЕСТО ТРЁХ

Это отдельный вид ошибки. Неважно, открыты карты или ещё нет и предполагается ли известной первоначальная первая карта.

1. Остановить игру и вызвать флора.
2. Дилер перемешивает эти четыре карты закрыто.
3. Флор случайно выбирает одну из них как следующий бёрн.
4. Остальные три становятся флопом.

Выбранная карта — следующий бёрн, то есть бёрн перед тёрном. При обычном продолжении второй дополнительный бёрн перед тёрном не делают.

Не путайте четыре карты флопа с тремя картами флопа без бёрна. В первом случае после выбора остаются три карты, во втором — две, которые дополняют следующей картой из остатка колоды.

Если одновременно допущено несколько ошибок, не составляйте собственную комбинацию исправлений. Флор определяет применимую процедуру по полным обстоятельствам.',NULL,'[]'::jsonb,'[]'::jsonb,4,true,false,true),
('69e6da5f-d1c0-5404-a85a-43b7dba8800f','37bc81e8-0868-5e56-8b0a-395ba7c266c1','Преждевременные улицы: флоп, тёрн и ривер','11. ПРЕЖДЕВРЕМЕННО ОТКРЫТ ФЛОП

Преждевременная улица — улица, выложенная до завершения торговли на предыдущей. “Забыли бёрн” и “поторопились открыть” могут выглядеть похоже, но требуют разных исправлений.

Порядок исправления для обычного преждевременного флопа с уже сделанным бёрном:
— исходный бёрн сохраняют;
— преждевременные три карты флопа возвращают в остаток колоды;
— весь этот остаток перетасовывают закрыто;
— исправленный флоп выкладывают без дополнительного бёрна.

Оставшиеся решения префлопа должны быть завершены до выкладывания исправленного флопа. Сам факт открытого борда не отменяет право пропущенного игрока на действие. Момент технической перетасовки в рамках остановки контролирует флор.

В перетасовку не включают уже сброшенные руки, прежние бёрны или карманные карты игроков. Перетасовывается остаток колоды с возвращёнными преждевременными картами.

Даже если один из тех же рангов снова появился на новом флопе, это не основание менять его ещё раз. Процедура восстанавливает случайность, а не гарантирует “совсем другие карты”.

12. ПРЕЖДЕВРЕМЕННО ОТКРЫТ ТЁРН

Порядок исправления при уже сделанном бёрне тёрна:
1. Остановить дальнейшее открытие карт и сохранить живые руки и ставки.
2. Сохранить бёрн тёрна отдельно: он остаётся бёрном.
3. Вернуть преждевременную карту тёрна в остаток колоды.
4. Перетасовать весь этот остаток закрыто.
5. Завершить необходимую торговлю флопа до выкладывания исправленного тёрна.
6. Если раздача продолжается до этой улицы, выложить исправленный тёрн без дополнительного бёрна.
7. После нормальной торговли тёрна ривер открывается в обычном порядке со своим бёрном.

Не откладывайте ранний тёрн с намерением заменить его «будущим ривером». Исправление выполняется возвратом раннего тёрна в остаток колоды, его закрытой перетасовкой и повторным выкладыванием тёрна без дополнительного бёрна.

Если последующее завершение торговли приводит к окончанию раздачи, не нужно всё равно открывать исправленную улицу ради демонстрации.

13. ПРЕЖДЕВРЕМЕННО ОТКРЫТ РИВЕР

Сохраняется бёрн ривера. Преждевременная карта возвращается в остаток колоды, весь этот остаток перетасовывается закрыто. После завершения необходимых решений тёрна, если раздача продолжается, выкладывают ривер без нового бёрна.

Не оставляйте преждевременный ривер только потому, что после его появления все согласились прочекать. Выставленная раньше времени карта не должна сама заменять установленную процедуру.

Общая памятка для преждевременных улиц:
Сохранить соответствующий бёрн → вернуть преждевременные общие карты в остаток → перетасовать остаток закрыто → завершить незаконченный предыдущий круг → выложить исправленную улицу без второго бёрна.

Не применяйте эту памятку вслепую, если одновременно отсутствовал бёрн, перемешались зоны или неизвестны карты: это уже составная ошибка для решения флора.

14. ПОЧЕМУ НЕ НУЖНО “ВОССТАНАВЛИВАТЬ ТОЧНЫЙ ПОРЯДОК КОЛОДЫ”

В СПЛ действует принцип: назначение бёрна — защищать остаток колоды, а не сохранять предсказанный исходный порядок карт.

Если после SA погибла рука с неверным числом карт, все её карты уходят в мак. Остаток колоды далее используется нормально: один бёрн перед каждой последующей улицей. Не добавляют второй бёрн из-за недостающей карты и не заменяют бёрн лишней картой из мёртвой руки.

Необходимые перетасовки остатка во время раздачи выполняются закрыто, не показывая карты. Это не обычная демонстрация состава колоды лицом вверх.',NULL,'[]'::jsonb,'[]'::jsonb,5,true,false,true),
('43018282-fe40-5dcf-84de-c805c2be275f','37bc81e8-0868-5e56-8b0a-395ba7c266c1','Раннее вскрытие и случайно забранная рука','15. ДИЛЕР СКАЗАЛ “ВСКРЫВАЕМСЯ”, НО ТОРГОВЛЯ НЕ ЗАКОНЧЕНА

Пример: на ривере A прочекал, B ещё должен действовать. Дилер ошибочно объявил вскрытие, и A открыл карты.

Объявление дилера не превращает незавершённый круг в завершённый. Не начинайте передавать банк. Сохраните обе руки и установите, чьё действие пропущено.

Преждевременное раскрытие при незавершённой торговле само по себе не делает руку мёртвой. В СПЛ нет автоматического ограничения “теперь только колл, без права ставки или повышения”. Допустимые действия определяются обычным состоянием торговли, а не таким вымышленным запретом.

Если A уже законно прочекал, открытие карт не даёт ему отменить этот чек. B получает своё оставшееся действие. Если B делает ставку, A отвечает на неё по обычным правилам, включая повышение, если оно разрешено состоянием торговли.

Возможное наказание рассматривает флор с учётом обстоятельств; оно начинается после окончания руки. Ошибку дилера и поведение игрока не нужно автоматически считать одним нарушением самого игрока.

16. ДИЛЕР СЛУЧАЙНО ЗАБРАЛ ЖИВУЮ РУКУ

Остановитесь, не продолжайте смешивать карты. Важнейший вопрос — можно ли установить руку со стопроцентной уверенностью.

Если смешанная рука может быть идентифицирована, она остаётся в игре, несмотря на раскрытие карт. Решение принимает флор по проверяемым обстоятельствам, а не по желанию игрока выбрать похожие карты из мака.

Если рука убита по ошибке дилера или признана смешанной и не может быть достоверно установлена, игрок не получает обратно уже уравненные ставки. Если он первым сделал ставку или повышение и часть не была уравнена, неуравнённая сумма возвращается.

Фраза игрока “у меня точно были два туза” сама по себе не даёт достоверной идентификации. Нельзя раздать ему новые две карты вместо погибшей руки.

Игрок обязан защищать руку, в том числе при вскрытии до её прочтения. Это не снимает с дилера обязанности аккуратно работать с картами.',NULL,'[]'::jsonb,'[]'::jsonb,6,true,false,true),
('3dbda2eb-30ad-50ae-bd8f-fc852745432e','37bc81e8-0868-5e56-8b0a-395ba7c266c1','Дефектная колода','17. ДЕФЕКТНАЯ КОЛОДА — ОТДЕЛЬНОЕ ИСКЛЮЧЕНИЕ

Колода fouled, если в ней обнаружены, например, две карты одинакового достоинства и масти или не предусмотренная игрой карта, такая как джокер в обычном холдеме. При другом подозрении на дефект колоды остановитесь и вызовите флора.

Если такой дефект обнаружен во время руки, игра останавливается и ставки возвращаются независимо от SA. Это исключение из обычного запрета пересдачи после SA.

Не называйте любую ошибку выкладывания карт дефектной колодой. Ранний тёрн при нормальной колоде — процедурная ошибка, а не основание возвращать всем все ставки.

После завершения руки право оспаривать результат из-за дефектной колоды ограничено сроками оспаривания, разобранными в блоке контроля стола. Не обещайте автоматически пересчитать уже законченный турнир по одному позднему заявлению.',NULL,'[]'::jsonb,'[]'::jsonb,7,true,false,true),
('f20c8dd0-7c6b-565f-8268-f11168a96cdd','267992d6-9a38-557c-89ce-1937e0d37d74','Объявление действия и обязательность колла','Объявления, спорные суммы, действия вне очереди, раскрытие и сброс карт

Задача блока

Научиться не угадывать намерение игрока, а устанавливать фактическое действие: что сказано, когда сказано, какие фишки внесены, чья очередь и какие действия уже последовали. Исправить спорную ставку и назначить наказание — разные задачи. Сначала восстанавливают правильное состояние игры, санкцию определяет флор.

Общий порядок

Остановить дальнейшие действия при споре → сохранить отдельные ставки и карты → установить очередь и последовательность слов и фишек → определить применимое правило → при неясности вызвать флора → зафиксировать итоговую сумму → продолжить с правильного игрока.

Нельзя объяснять все случаи одной фразой «слово всегда важнее фишек» или «всё, что вышло за линию, всегда рейз». Правила СПЛ учитывают порядок действий, контекст, количество фишек и специальные исключения.

1. СНАЧАЛА УСЛЫШАТЬ, ПОТОМ ДВИГАТЬ ФИШКИ

Если игрок и объявляет действие, и выдвигает фишки, действие определяется тем, что было первым. При одновременном действии ясное и разумное объявление имеет приоритет; в противном случае играют фишки. Неясное противоречие разбирает флор с учётом обстоятельств.

Пример: игрок в свою очередь сначала ясно сказал «колл», потом поставил фишки с избытком. Избыток не превращает колл в рейз сам по себе. Сначала установлен колл, затем проверяется оплата и сдача.

Другой пример: игрок сначала молча поставил одну крупную фишку в ответ на ставку и только потом сказал «я хотел рейз». Позднее объяснение не отменяет уже совершённый колл по правилу одной фишки.

Объявление конкретной суммы без слова «рейз» рассматривается так же, как молчаливое внесение такой суммы. «Тысяча четыреста» в ответ на первую ставку 1 000 не означает обязательный рейз только потому, что сумма произнесена вслух: применяются правила размеров и повышения.

Не сгребайте фишки и не выдавайте сдачу до установления действия. Если игрок сказал неразборчиво и сразу возник спор, сохраните исходную раскладку.

2. КОЛЛ — ОБЯЗАТЕЛЬСТВО ОТВЕТИТЬ НА ПОЛНУЮ СТАВКУ

Общее объявление «колл» в свою очередь связывает игрока полной текущей суммой. Если он сказал «колл» и поставил меньше, нельзя автоматически разрешить ему оставить только внесённую часть и отказаться от остального.

Пример: ставка перед игроком 1 200. Он ясно говорит «колл» и ставит 800 при достаточном стеке. Сумму нужно привести к полному коллу 1 200 по применимому правилу, а не считать оплатой только 800.

Принятая ставка обычно связывает игрока её правильным размером, даже если при запросе счёта дилер ошибочно назвал меньшую сумму. В необычных обстоятельствах окончательное решение принимает флор в интересах справедливой игры. Дилер не должен обещать ни автоматический возврат, ни наказание без разбора.

Полезное предотвращение: игроки должны дождаться ясной суммы ставки до своего действия. «Колл» на ещё не определённый рейз может связать игрока суммой, которую он не ожидал; такой случай разбирает флор по правилам СПЛ.',NULL,'[]'::jsonb,'[]'::jsonb,0,true,false,true),
('ee430c85-d98c-5548-a630-29323d16b488','267992d6-9a38-557c-89ce-1937e0d37d74','Одна и несколько фишек, порог 50%','3. ОДНА КРУПНАЯ ФИШКА

Если игрок отвечает на ставку или блайнд одной крупной фишкой без предварительного объявления рейза, это колл. Даже если это его последняя фишка, она не становится автоматически рейзом на всю стоимость.

Пример: ставка 600, игрок ранее в этом круге ничего не вносил, молча поставил одну фишку 1 000. Колл 600, сдача 400.

Для повышения одной крупной фишкой слово «рейз» должно прозвучать до касания фишкой поверхности стола. При объявлении рейза без суммы повышение этой фишкой определяется её полной допустимой стоимостью, с соблюдением минимального размера повышения.

Если перед игроком ставки нет, молчаливое внесение одной фишки 1 000 — ставка 1 000, если она допустима, а не колл. Всегда сначала проверяйте, отвечает ли игрок на ставку.

4. НЕСКОЛЬКО ФИШЕК: СНАЧАЛА ПРОВЕРКА НЕОБХОДИМОСТИ

Если перед внесением не объявлены рейз или олл-ин, проверяют, нужна ли каждая внесённая фишка для покрытия колла. Если убрать одну из самых мелких фишек и оставшегося уже недостаточно, это колл.

Пример: колл стоит 1 200. Игрок молча ставит две фишки по 1 000. Убрать одну — останется 1 000, меньше требуемых 1 200. Поэтому это колл 1 200, сдача 800, а не рейз до 2 000. При таких же условиях правило действует и для последних фишек игрока, если рейз или олл-ин не объявлены заранее.

Если одну из самых мелких фишек можно убрать, а оставшихся всё равно хватает на колл, тогда при наличии фишек за спиной применяется стандарт 50%. Для последних фишек действует отдельное условие: если проверка необходимости не дала колл, это олл-ин даже при недостижении порога 50%.

Не начинайте с расчёта 50%, пропустив проверку необходимости всех фишек. И не делайте общего вывода «любые последние фишки всегда полное повышение».

5. КАК РАБОТАЕТ ПОРОГ 50%

Минимальное повышение рассчитывается по величине последней полной ставки или повышения текущего круга, а не всегда по BB.

Простой пример: первая ставка улицы — 1 000. Полное минимальное повышение — ещё 1 000, то есть до 2 000.

Если игрок без объявления рейза, не в олл-ине, вносит несколько фишек на 1 500 и по правилу нескольких фишек это не колл, его прибавка составляет 500. Это 50% полного повышения. Он обязан довести до минимального рейза 2 000.

Например, молча внесены три фишки по 500. Можно убрать одну и оставить 1 000, значит, все фишки не необходимы для колла. Прибавка 500 достигает порога. Итог — обязательное дополнение до 2 000.

Если при первой ставке 1 000 молча внесены одна фишка 1 000 и четыре по 100, всего 1 400, и игрок не в олл-ине, это колл 1 000 со сдачей 400: прибавка меньше половины полного повышения.

Если «рейз» объявлен заранее, недостаточная сумма не становится коллом только из-за порога ниже 50%: применяются обязательство повышения и правила допустимого олл-ина.

В более сложной последовательности сначала найдите последнее полное повышение. BB 200, игрок повышает до 600: прибавка 400. Следующий полный минимальный рейз — до 1 000, а не до 1 200.

6. ПРЕЖНИЕ ФИШКИ ИГРОКА ЕЩЁ ЛЕЖАТ ПЕРЕД НИМ

Отдельно регулируется добавление к прежней ставке, которая ещё не собрана. Нельзя механически применить правило одной новой фишки без учёта того, как игрок обращался со старыми.

Установите: сколько было раньше; покрывали ли прежние фишки новую сумму колла; игрок оставил их, полностью забрал назад или забрал только часть; что именно добавил; было ли объявление.

Если игрок, столкнувшись с повышением, явно забирает назад прежнюю ставку, он связывает себя коллом или рейзом и не может просто вернуть фишки обратно и затем сфолдить по своему желанию.

Не разбирайте сложную перекладку в ускоренном темпе. Сохраните финальную и исходную суммы, последовательность движений и вызовите флора, если неясен применимый вариант. Лучшее предотвращение — ясное объявление игроком действия до изменения фишек.',NULL,'[]'::jsonb,'[]'::jsonb,1,true,false,true),
('86af4671-ea58-591f-9d98-8d630bac1ec0','267992d6-9a38-557c-89ce-1937e0d37d74','Недостаточный колл','7. ВНЕСЕНО МЕНЬШЕ КОЛЛА БЕЗ СЛОВА “КОЛЛ”

Undercall — объявлена или внесена сумма меньше требуемого колла без предварительного общего объявления «колл».

Обязательное доведение до полного колла применяется, если действие сделано в очередь:
— в ответ на любую ставку, когда в руке осталось двое;
— в ответ на первую ставку круга при нескольких участниках.

На префлопе выставленный BB считается первой ставкой. Чек первой ставкой не является.

Пример: на флопе A первым ставит 1 000. B молча вносит 500, имеет достаточно фишек и ещё не находится в олл-ине. Это ответ на первую ставку: требуется полный колл 1 000.

Другой случай: за несколькими игроками A ставит 1 000, B повышает до 3 000, C молча вносит 1 000. Это undercall в ответ на повышение, а не на первую ставку круга. Здесь решение за флором; нельзя обещать обязательное разрешение сфолдить с потерей 1 000 или безусловно требовать все 3 000, не разбирая обстоятельств.

Если несколько undercall подряд, игра возвращается к первому для исправления по правилам СПЛ, а дальнейшие руки разбирает флор.',NULL,'[]'::jsonb,'[]'::jsonb,2,true,false,true),
('0cbdc44b-130a-56c5-9d39-30bf9a6034d2','267992d6-9a38-557c-89ce-1937e0d37d74','Неправильный рейз и короткий олл-ин','8. STRING BET: ПОСТАВИЛ, ПОТОМ ВЕРНУЛСЯ ЗА ДОБАВКОЙ

Правила СПЛ запрещают ставки и повышения несколькими несвязанными движениями: игрок выдвинул ставку, затем вернулся к стеку и добавил ещё без заранее установленной полной суммы.

Безлимитное повышение должно быть либо внесено полной суммой одним движением, либо полная сумма должна быть объявлена до выдвижения фишек.

Пример: игрок заранее ясно сказал «рейз до двух тысяч». После этого физическое выкладывание объявленной полной суммы не превращается в произвольный выбор нового размера на каждом движении.

Но просто сказать «рейз» и затем поэтапно выбирать неизвестную сумму, наблюдая реакцию соперника, — не равно заранее объявить полный размер. Не преподавайте старую схему «сначала колл, потом ещё один жест с повышением» как универсально разрешённый способ.

При споре зафиксируйте точные слова и движения. Не позволяйте последующим объяснением незаметно переписать уже совершённое действие.

9. СТАВКА ИЛИ РЕЙЗ НИЖЕ МИНИМУМА

Не путайте undercall, недостаточное повышение и законный короткий олл-ин.

В limit и no-limit неправильно оформленную ставку или повышение ниже минимума исправляют на текущей улице; на ривере — до начала вскрытия. Это не отменяет специальные правила, определяющие, было ли действие вообще коллом, а не рейзом, и исключение законного короткого олл-ина.

Пример: BB 200, после флопа A ставит 600, B повышает до 1 000, то есть добавляет только 400 вместо необходимых 600. Если это установленный рейз, а не колл по иной норме, при обнаружении ошибки до тёрна ставку приводят к 1 200 для участвующих в этом действии игроков. После выкладывания следующей улицы такая ошибка остаётся как есть по данному правилу.

Не открывайте следующую улицу, пока известная ошибка ставки текущего круга не разобрана.

10. КОРОТКИЙ ОЛЛ-ИН И ПРАВО НА ПОВЫШЕНИЕ

В no-limit неполное повышение не всегда открывает рейз уже действовавшему игроку. Сравнивают, на какую суммарную прибавку он отвечает при возврате действия, с величиной необходимого полного повышения.

Пример: A ставит 1 000. B идёт в олл-ин до 1 500. Остальные, если есть, не повышают. Для A прибавка только 500 при необходимом полном повышении 1 000. Поэтому A может уравнять или сбросить, но право повышать этим единственным коротким олл-ином не открыто.

Игрок C, который ещё не действовал, не лишается права рейза просто из-за короткого олл-ина B. Если у него достаточно фишек и других ограничений нет, минимальный рейз в этой ситуации — до 2 500: текущие 1 500 плюс последняя полная величина 1 000.

Несколько коротких олл-инов могут суммарно открыть право на повышение. Например: A ставит 100, B олл-ин 125, C колл 125, D олл-ин 200. Когда действие возвращается к A, прибавка к его 100 равна полному повышению 100 — право открывается. Для C, который уже уравнял 125, разница до 200 только 75: без других изменений право не открывается.

Права проверяются для каждого участника отдельно. Порог 50% в этой теме не нужно переносить из limit в no-limit: это разные правила.',NULL,'[]'::jsonb,'[]'::jsonb,3,true,false,true),
('a5ee5087-1eda-5a83-96d7-87e7c525d1e4','267992d6-9a38-557c-89ce-1937e0d37d74','Внеочередной ход и пропущенный игрок','11. ВНЕОЧЕРЕДНОЙ ХОД ПРИ ТРЁХ И БОЛЕЕ УЧАСТНИКАХ РУКИ

OOT — действие вне очереди. Действие возвращают правильному игроку. Важно, изменится ли сумма ставки, на которую отвечает нарушитель.

Пример: A ещё должен действовать, B вне очереди объявляет чек. Если A чекает, условия для B не меняются и его чек связывает. Если A ставит, условия меняются; при нескольких участниках B получает обычные доступные варианты ответа на новую ставку.

Пример со ставкой: перед A ставка 300, B вне очереди объявил рейз до 800. Если A коллирует или сбрасывает, сумма перед B остаётся 300, его внеочередной рейз связывает. Если A повышает до 600, сумма перед B изменилась: первоначальное действие B не связывает, фишки возвращаются, у него вновь доступны колл, допустимый рейз или фолд.

Чек, колл и фолд правильного игрока сами по себе не меняют сумму ставки для нарушителя. Внеочередной фолд связывает отдельно: это не способ сохранить право забрать сброшенную руку после чужого повышения.

Возможное наказание за OOT определяет флор. Возврат фишек при изменении действия не означает, что нарушения не было.

12. ВНЕОЧЕРЕДНОЙ ЧЕК В ХЕДЗ-АПЕ РУКИ

Отдельно рассматривается ситуация, когда в этой руке осталось ровно двое. Это может быть и остаток раздачи за большим столом — не обязательно финальный стол из двух человек.

Если B пассивно действует вне очереди, то есть чекает до положенного действия A, то на ставку A он может только коллировать или сфолдить. Повышать в этом круге ему нельзя.

Пример: до тёрна дошли двое. Первым должен действовать A, но B поспешил и объявил чек. A ставит 1 000. B может колл или фолд, но не рейз.

Это не противоречит правилу про преждевременное раскрытие карт. Запрет повышения здесь следует из правила внеочередного чека при двух участниках, а не из самого показа карт. Не путайте причины ограничения.

Сравните два примера: внеочередной чек при трёх участниках и такой же чек при двух. В этих ситуациях применяются разные последствия внеочередного чека.

13. ПРОПУЩЕННЫЙ ИГРОК НЕ ДОЛЖЕН МОЛЧА ОЖИДАТЬ

Игрок, которого пропустили внеочередными действиями, обязан защищать право на ход. Если у него было разумное время заявить об ошибке, но после него успели произойти SA вне очереди, действия после него становятся обязательными, а судьбу пропущенной руки определяет флор.

Возможны ограничения до неагрессивных действий или признание руки мёртвой — по обстоятельствам. Это не разрешение дилеру автоматически убивать руку после любого чужого движения и не гарантия игроку бесконечного возврата действия назад.

Как только дилер заметил пропуск, нужно остановить цепочку и вернуть действие до нарастания ошибки.',NULL,'[]'::jsonb,'[]'::jsonb,4,true,false,true),
('bb23e269-441f-5538-b1ab-c539fa34e058','267992d6-9a38-557c-89ce-1937e0d37d74','Ошибочные слова и попытка размена','14. “ЧЕК” ПЕРЕД СТАВКОЙ И ДРУГИЕ НЕВЕРНЫЕ СЛОВА

Применяются следующие правила:
— если ставки перед игроком нет, объявление «колл» считается чеком;
— если ставки нет, объявление «рейз» обязывает сделать как минимум допустимую минимальную ставку;
— если игрок объявил «чек», отвечая на уже существующую ставку, он может коллировать или сбросить, но не повышать.

Последнее ограничение — конкретное правило ошибочного объявления, а не общее наказание за любой показ руки.

Не разрешайте «чек» поверх ставки как законный бесплатный проход дальше. Не исправляйте чужую оговорку подсказкой, выгодной одному участнику: установите действие по правилу.

15. “Я ПРОСТО ХОТЕЛ РАЗМЕНЯТЬ”

Нельзя использовать ставку как произвольный размен. Молчаливо выдвинутые фишки рискуют быть признанными частью ставки.

Пример: первая ставка 325. Игрок молча ставит 500 и 25, всего 525, ожидая 200 сдачи. Одну мелкую фишку 25 можно убрать и всё равно оставить достаточно для колла. Прибавка 200 превышает половину полного повышения 325. Поэтому по правилу нескольких фишек требуется повышение до 650, а не колл со сдачей.

Сначала определяют игровое действие и лишь затем делают размен. Объяснение намерения после выдвижения не гарантирует отмену ставки.',NULL,'[]'::jsonb,'[]'::jsonb,5,true,false,true),
('6d3309bf-c401-5561-99fc-e6c32e544139','267992d6-9a38-557c-89ce-1937e0d37d74','Неясные суммы, условные фразы и запросы счёта','16. НЕЯСНЫЕ СУММЫ, УСЛОВНЫЕ ФРАЗЫ И ЗАПРОСЫ СЧЁТА

«Если поставишь, я повышу» — не стандартное действие в очередь. Условная фраза может быть признана обязательной и/или наказуемой по усмотрению флора. Не обещайте заранее, что такие слова всегда ничего не значат.

Неясные суммы вроде «пять» разбирают по правилам СПЛ с учётом допустимых значений, банка и контекста. Дилер не должен подсказывать игроку, какое толкование для него выгоднее.

В no-limit дилер не считает банк по запросу как в pot-limit. Точный счёт чужого стека можно запросить, когда игрок сталкивается с олл-ином и настала его очередь; дилер или флор считают по такому запросу. Это не право в любой момент требовать точный пересчёт любого чужого стека.

Доступность разумной оценки и видимость крупных номиналов помогают игре. Тайная фишка, обнаруженная за спиной после объявленного олл-ина и колла, разбирается флором по правилам СПЛ, а не автоматически спасает проигравшего от вылета.',NULL,'[]'::jsonb,'[]'::jsonb,6,true,false,true),
('c7a427d4-15b2-54f0-af7f-4f97d9af8ca5','267992d6-9a38-557c-89ce-1937e0d37d74','Фолд, раскрытие карт и подсказки','17. ФОЛД, РАСКРЫТИЕ И ЧУЖИЕ ПОДСКАЗКИ

Фолд вне очереди связывает; фолд в очередь, когда ставки нет и последняя торговля ещё не завершена, также связывает и может повлечь санкцию. Нельзя забрать руку обратно только потому, что после раннего фолда условия стали привлекательнее.

Показ карт при незавершённом действии сам по себе не делает руку мёртвой. Возможное наказание начинается после окончания руки. Нужно отдельно установить, было ли также обязательное объявление фолда или иное действие: открытые карты и сброшенные карты — не одно и то же.

Действует принцип «один игрок — одна рука»: нельзя советовать решение, обсуждать содержимое живых или сброшенных рук, читать ещё не выложенную для общего просмотра руку. Эти ограничения касаются и уже вышедших из раздачи участников.

Дилер пресекает обсуждение, сохраняет факты и обращается к флору. Не назначает сам универсальный штраф «один круг» за любой случай.',NULL,'[]'::jsonb,'[]'::jsonb,7,true,false,true),
('3e74ef2a-27d3-578b-b965-1fcfb3adcd64','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','Контроль стола и понятные объявления','Задача блока

Научиться вести стол спокойно, понятно и нейтрально: контролировать очередь, объявлять нужную информацию, предотвращать путаницу и правильно передавать спор флору. Контроль — это не громкость и не постоянное вмешательство в решения игроков. Хороший дилер создаёт понятную игру и не превращает её в спор о собственной правоте.

Все процедуры блока относятся к правилам СПЛ. Они применяются вместе с описанными ранее правилами анте, смены уровня по гонгу, балансировки и округления при выводе номиналов.

Основной рабочий цикл

Наблюдать → определить, кому действие → ясно объявить существенную информацию → проверить завершение действия и суммы → только после этого перейти дальше.

При споре:
Остановить затронутые действия → сохранить карты и фишки → кратко описать факты → вызвать флора → дать ему установить обстоятельства → выполнить решение → проверить восстановленную очередь и суммы → продолжить.

1. ЧТО ДИЛЕР КОНТРОЛИРУЕТ ПОСТОЯННО

Не только свою колоду и руки. Нужно видеть:
— кто ещё в раздаче и кто уже сбросил;
— чья очередь и кому ещё предстоит ответить;
— есть ли ставка, повышение или олл-ин;
— правильно ли различимы вклады текущего круга;
— не скрыты ли живая рука или крупные фишки;
— завершена ли торговля перед открытием улицы;
— нет ли просьбы остановиться из-за ошибки;
— можно ли ещё проверить руки и суммы до передачи банка.

Если дилер смотрит только на борд, он может не заметить живые карты под рукой, пропущенный ход или крупную фишку за мелкими стопками. Контроль стола — это последовательное внимание к игровому состоянию, а не угадывание намерений.

2. КАК ГОВОРИТЬ: КОРОТКО, ЯСНО, БЕЗ СТРАТЕГИЧЕСКИХ КОММЕНТАРИЕВ

Используйте понятные объявления: «Действие за вами», «Ставка — 600», «Повышение до 1 800», «Олл-ин», «Остановитесь, пожалуйста, требуется уточнение», «Флор, к столу».

Суммы называйте однозначно. «До 1 800» — итоговая ставка. «Добавить 1 200» — разница для конкретного игрока. Не заменяйте одно другим, если это может запутать стол.

Не говорите: «Ему недорого доставить», «Тут уже надо коллировать», «У вас почти наверняка деление», «Он блефует». Это подсказки или влияние на решения.

Если нужно вернуть очередь, обозначьте её, а не оценку поведения: «Сейчас действие за игроком 3» вместо «Вы опять всё портите».

Удобный тон — спокойный, достаточно слышимый всему столу. Повышать голос ради демонстрации власти не нужно. Если вас не слышат из-за конфликта, остановите игру и привлеките персонал, а не соревнуйтесь в крике.

3. ЧТО ОБЪЯВЛЯТЬ О СТАВКАХ И ОЛЛ-ИНЕ

В СПЛ предусмотрено обычное объявление сумм не олл-иновых ставок по мере торговли. Игрокам должна быть понятна сумма, на которую они отвечают.

Олл-ин нужно обозначить явно. Если используются специальные таблички, их следует размещать их дилером перед игроком так, чтобы всем был виден статус.

Не пересчитывайте автоматически каждый олл-ин до последней фишки, если ещё не было корректного запроса. Точный подсчёт выполняется по запросу игрока, перед которым сейчас действие и который отвечает на этот олл-ин.

Если запрос поступил от игрока не в очередь или уже сбросившего карты, не позволяйте ему управлять темпом и решениями действующего участника. Сохраняйте видимость стека и применяйте правило корректного запроса.

Не объявляйте приблизительную оценку как точную сумму. Если при точном счёте обнаружена ошибка в ранее озвученной сумме, немедленно сообщите её и при споре вызовите флора; принятая ставка разбирается по правилам СПЛ.',NULL,'[]'::jsonb,'[]'::jsonb,0,true,false,true),
('a2264672-4861-5e5f-966d-3ebf5c1dcfba','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','Очередность, видимость карт и сохранение ставок','4. ВЕРНУТЬ ОЧЕРЕДЬ ДО ТОГО, КАК ОШИБКА ВЫРОСЛА

Если игрок потянулся ставить вне очереди, предупредите: «Момент, сначала действие за игроком 2». Если действие уже совершено, зафиксируйте его и примените соответствующее правило, при необходимости с флором.

Не считайте предупреждение разрешением отменять любые уже обязательные слова. Не создавайте правило «если дилер успел сказать стоп, всё сказанное не считается».

Пропущенный игрок должен защищать право на действие. Молчание до существенных внеочередных действий после него может иметь последствия. Поэтому дилеру важно заметить пропуск сразу, а не после завершения всего круга.

Контроль не должен превращаться в подсказку: сообщить игроку сумму ставки — информация; посоветовать колл — вмешательство в игру.

5. КАРТЫ И СТЕКИ ДОЛЖНЫ БЫТЬ ВИДНЫ

Живые руки должны оставаться на виду. Крупные номиналы должны быть видны и различимы. Для стеков игроков правило предусматривает чистые вертикальные стопки по 20 фишек одного номинала; остатки раскладывают понятно, а не прячут внутри других групп.

Это организация стека игрока, а не запрет дилеру разложить проверяемую сумму группами по пять при подсчёте. Не путайте видимость постоянного стека и временную счётную раскладку.

Если крупная фишка скрыта, попросите: «Поставьте, пожалуйста, крупные номиналы так, чтобы они были видны». Если карты спрятаны за стеком: «Карты, пожалуйста, оставьте на виду».

Не тянитесь без необходимости менять защищённый стек или руку игрока. Если он отказывается выполнять требование видимости, остановите развитие проблемы и вызовите флора.

Видимость не означает право любого участника в любой момент требовать точный пересчёт чужого полного стека. Разумная оценка и точный счёт — разные права.

6. СТАВКИ НЕ НУЖНО ПОСТОЯННО СГРЕБАТЬ В ЦЕНТР

В СПЛ не следует рутинно подтягивать ставки в банк, пока торговля и повышения продолжаются. Это может скрыть суммы, повлиять на действие и привести к ошибкам.

Сохраняйте вклады различимыми до завершения круга и проверки неуравнённых частей и разных олл-инов. В ходе торговли попросить дилера подтянуть ставки может игрок, перед которым сейчас действие, а не любой наблюдатель.

В no-limit дилер не пересчитывает банк по запросу как в pot-limit. По запросу можно разложить фишки банка для лучшей видимости, не подменяя это объявлением точного счёта в формате, где он не предоставляется.

Обещание «я буду вслух считать весь банк после каждой ставки» не является стандартом хорошего контроля no-limit стола.',NULL,'[]'::jsonb,'[]'::jsonb,1,true,false,true),
('b5949583-835c-5bea-8cb7-a1886ade108b','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','Передача спора флору и продолжение игры','7. КАК ПЕРЕДАТЬ СПОР ФЛОРУ

Не нужно рассказывать историю на несколько минут. Используйте короткую фактическую форму:
1. Где мы: улица, число участвующих рук, чья очередь.
2. Что произошло: точные слова, суммы, движения или ошибка.
3. Что уже последовало: действия других игроков и открытые карты.
4. Что сохранено: отдельные фишки, рука, остаток колоды, бёрн.
5. Что нужно установить: итог действия, сумму или применимую процедуру.

Пример: «Ривер, трое в раздаче. A поставил 1 000, B повысил до 3 000. C молча внёс 1 000, слова “колл” не было. Следующих действий нет, фишки отдельно. Требуется решение по undercall».

Не заменяйте факты выводом «он точно хотел обмануть». Мотив и наказание устанавливаются не по раздражению дилера.

Если чего-то не слышали, прямо скажите: «Эту часть объявления я не расслышал». Не восстанавливайте уверенную цитату из догадки.

8. ЧТО СОХРАНИТЬ ДО ПРИХОДА ФЛОРА

Не смешивайте спорные ставки. Не убирайте живые руки и открытый борд, нужные для проверки. Не меняйте положение спорной фишки без необходимости и не выполняйте техническое исправление раньше установления процедуры.

Остановите последующие действия, которые могут сделать решение сложнее: новую улицу, передачу банка или следующую раздачу. Не нужно ради паузы физически удерживать игрока или отбирать его вещи.

Дайте участникам кратко изложить факты по очереди. Пресекайте подсказки по ещё живой руке и давление на свидетелей. Не разрешайте всему столу одновременно предлагать выгодные разным игрокам трактовки.

После прихода флора отвечайте по существу. Не спорьте с ним перед столом, отстаивая собственную репутацию. Решения флора окончательны в рамках установленного управления турниром; необычные обстоятельства могут требовать решения в интересах справедливости выше буквальной механики отдельного пункта.

9. КАК ПРОДОЛЖИТЬ ПОСЛЕ РЕШЕНИЯ

Недостаточно услышать «играем дальше» и открыть карту. Убедитесь, что вы поняли:
— чья рука жива;
— какой итог действия и сумма ставки;
— какие фишки остаются, какие дополняются или возвращаются;
— кто действует следующим;
— требуется ли исправление борда или колоды;
— есть ли назначенная санкция и когда она начинается.

Кратко повторите итог нейтрально: «Колл до 1 200, требуется добавить 400. Затем действие за игроком 5». Если указание неясно, уточните до продолжения.

Не обсуждайте, кто «выиграл спор». Вернитесь к нормальному ведению стола.',NULL,'[]'::jsonb,'[]'::jsonb,2,true,false,true),
('591dbafb-0dcf-5f1b-ac58-c31c433a413e','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','Затягивание игры и отсчёт времени','10. ДОЛГОЕ РЕШЕНИЕ И ЗАПРОС CLOCK

Правила СПЛ требуют разумного темпа. Если по оценке турнирного директора разумное время уже прошло, он может назначить отсчёт или одобрить запрос игрока турнира. Для запроса игрок должен находиться в пределах досягаемости своего стула.

Дилер не должен по собственному раздражению запускать любой придуманный таймер, например «у вас всегда 15 секунд». Запрос не равен автоматическому началу отсчёта без предусмотренного решения.

Базовый порядок отсчёта: до 25 секунд на действие плюс пятисекундный обратный отсчёт. Турнирный директор вправе менять предоставляемое время и меры с учётом обстоятельств и систематического затягивания.

Если время истекло и перед игроком есть ставка, рука мертва. Если ставки перед ним нет, объявляется чек. При совпадении действия и истечения времени преимущество отдаётся игроку.

Порядок для дилера: принять запрос → привлечь уполномоченный персонал → сообщить факты о длительности и характере ситуации → исполнять назначенную процедуру → объявить итог по правилу.

Отсчёт clock за игровым столом не нужно путать с таймером учебного тренажёра или экзамена: это разные процедуры.',NULL,'[]'::jsonb,'[]'::jsonb,3,true,false,true),
('a24567f4-b5c6-587e-b49d-a9e5ef1a526e','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','Конфликты, подсказки и устройства','11. ОСКОРБЛЕНИЯ, ДАВЛЕНИЕ И ОПАСНОЕ ПОВЕДЕНИЕ

Запрещены оскорбления, угрозы, агрессия, дискриминация, бросание карт и фишек в людей, систематическое разрушение игры и другое недопустимое поведение.

При обычном нарушении спокойно обозначьте требование: «Без оскорблений, пожалуйста». Если поведение продолжается, вызывает спор или требует санкции, вызовите флора. Не вступайте в ответную перепалку и не унижайте игрока.

При угрозе безопасности сразу привлекайте ответственный персонал и охрану по порядку площадки; обычное продолжение игры не важнее безопасности. Порядок безопасности не заменяет решение флора об игровых последствиях и санкциях.

Не пытайтесь своими силами удерживать агрессивного человека или физически разрешать конфликт. Сохраняйте безопасную дистанцию и возможность персоналу вмешаться.

12. ПОДСКАЗКИ И ОБСУЖДЕНИЕ КАРТ

Принцип «один игрок — одна рука» действует для всех, включая уже сбросивших карты. Нельзя обсуждать содержимое живых и сброшенных рук, советовать решения или читать ещё не выложенную для общего просмотра руку.

Пример: игрок вышел из раздачи и говорит «я выбросил две пики», пока другие ещё принимают решения. Это не безобидный комментарий, а информация, влияющая на игру. Дилер должен остановить обсуждение и сообщить нарушение при необходимости флору.

Короткая фраза: «Не обсуждаем карты, пока раздача продолжается». Не повторяйте саму раскрытую информацию громко всему залу без нужды.

Но после корректного вскрытия ситуация иная: по правилам СПЛ любой человек должен сообщить, если видит ошибку чтения открытой руки или расчёта и передачи банка. Это не запрещённая стратегическая подсказка, а защита правильного результата.

13. ТЕЛЕФОНЫ И ВНЕШНЯЯ ПОМОЩЬ

Игроки не разговаривают по телефону за столом; устройства не должны создавать помехи или преимущество, телефон и другие устройства не размещают на столе. Игрок с живой рукой не взаимодействует с электронным или коммуникационным устройством. Приложения, таблицы и иные инструменты стратегии за столом запрещены; внешние советы и данные стратегии также не допускаются.

Новейшие устройства и специальные разрешения регулируются TD. Не считайте отсутствие обычного телефона доказательством отсутствия внешней помощи: правило охватывает и новые технологии, включая скрытую связь.

Спокойно обозначьте конкретное требование и при отказе или подозрении на нарушение вызовите флора. Дилер не получает от этого право самостоятельно просматривать личную переписку, требовать пароль или забирать устройство.

Не превращайте правило в утверждение «любой телефон в кармане запрещён»: речь о конкретных ограничениях размещения, использования и помощи.',NULL,'[]'::jsonb,'[]'::jsonb,4,true,false,true),
('3f780a23-65ce-59f3-9de5-42d2fe8a1f9c','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','Отсутствующий игрок и исполнение штрафа','14. ОТСУТСТВУЮЩИЙ ИГРОК И ЖИВАЯ РУКА

Чтобы рука была живой, игрок должен находиться на своём месте к моменту окончания исходной сдачи последней карты всем игрокам. «На месте» означает в пределах досягаемости своего стула.

Если к этому моменту его нет, он не вправе смотреть свои карты, рука немедленно гасится, выставленные блайнды и анте остаются в банке. Не позволяйте оживить её только потому, что игрок прибежал до своего первого решения.

Участник с живой рукой, включая олл-ин или уже закончившего ставить, должен оставаться у стола во все круги и до вскрытия. Сам факт олл-ина не разрешает уйти и перестать защищать руку.

Процедура присутствия одинакова во всех блоках курса: окончание исходной сдачи последней карты всем — контрольный момент для живой руки отсутствовавшего участника.

15. НАКАЗАНИЕ НАЗНАЧАЕТ ФЛОР, ДИЛЕР ЕГО ИСПОЛНЯЕТ

Возможны предупреждения, пропуск раздач или кругов, предусмотренные штрафы фишками и дисквалификация. Это не жёсткая лестница «первый раз всегда предупреждение, второй всегда один круг». Повторность и тяжесть учитывает уполномоченный персонал.

При штрафе в пропущенных кругах число пропускаемых раздач рассчитывается по числу игроков за столом, включая нарушителя, на момент назначения, умноженному на количество кругов штрафа. Указание должен дать и подтвердить флор.

Пример: за столом восемь игроков, назначен один missed round — восемь пропускаемых раздач по формуле правила. Два таких круга при той же исходной численности — шестнадцать. Не определяйте самостоятельно точку начала и не меняйте объявленный отсчёт без подтверждения при особых событиях.

Игрок на штрафе находится вне стола. Карты на его место сдаются, блайнды и анте выставляются, рука гасится после исходной сдачи. Это не освобождение от обязательных ставок; игрок может потерять весь стек на них. При пересдаче исходная сдача и её повтор считаются одной раздачей для штрафа.

Фишки дисквалифицированного убираются из игры. Их не раздают остальным как свободный банк.',NULL,'[]'::jsonb,'[]'::jsonb,5,true,false,true),
('39ee470f-8314-54fa-9446-bd75bfe5f3ef','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','Вскрытие, сроки спора и запрет досмотра борда','16. ВСКРЫТИЕ: ФАКТИЧЕСКИЕ КАРТЫ ВАЖНЕЕ ОГОВОРКИ

Дилер читает и объявляет фактическую силу руки. Если игрок назвал пару, а открытые карты дают стрит, оценивается стрит. Умышленное ложное объявление может быть наказуемым, но не даёт права выдать банк заведомо неверно.

Для корректного вскрытия обе карманные карты в холдеме должны лежать лицом вверх и позволять прочитать руку. Игрок защищает их до прочтения. Дилер не может убить корректно выложенную очевидно победившую руку.

Не убирайте доказательства быстрее, чем установлены результат и право на каждый банк. Каждый побочный банк проверяется и делится отдельно по правилам СПЛ.

Если кто-то сообщает об ошибке чтения или суммы, не отвечайте «поздно, я уже сказал победителя». Сначала установите, какой спор заявлен и не истёк ли применимый срок.

17. СРОКИ СПОРА И ЗАПРЕТ “ДОСМОТРЕТЬ БОРД”

В СПЛ различают два вида спора:
— чтение уже выложенной руки можно оспаривать до начала следующей раздачи;
— ошибку расчёта и передачи банка — до SA следующей раздачи.

Если рука завершилась во время перерыва, срок для любого такого спора заканчивается через минуту после передачи банка. Для срока оспаривания чтения руки следующая раздача считается начатой при первом рифле, запуске шаффлера или смене дилера. Это контрольная граница спора. Уровень блайндов в СПЛ определяется отдельно по гонгу и наличию хотя бы одного выставленного блайнда, как описано в турнирном блоке.

Не обещайте бесконечный пересмотр, но и не сокращайте срок собственным объявлением «банк поехал, всё». Сохраняйте факты и зовите флора.

Rabbit hunting запрещён: после досрочного окончания раздачи нельзя открыть оставшиеся общие карты только ради любопытства, даже если участники просят показать, “что бы пришло”. Это не продолжение живой раздачи.',NULL,'[]'::jsonb,'[]'::jsonb,6,true,false,true);
insert into public.learning_questions(prompt,options,correct_index,id,section_id,lesson_id,cards,sort_order,published,archived,ever_published) values
('Какова основная задача дилера во время раздачи?','["Подсказать неопытному игроку выгодное действие", "Нейтрально вести игру и контролировать её правильность", "Обеспечить победу игроку с самым большим стеком", "Определять ставки игроков вместо них"]'::jsonb,1,'db343369-66d8-5679-afeb-35b5dda585c1','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','ed95281f-5a39-5f27-94ca-af9314338e39','[]'::jsonb,0,true,false,true),
('На столе пять общих карт, у игрока две карманные. Сколько карт составляет его итоговую комбинацию?','["Две: только карманные карты", "Семь: все доступные карты", "Шесть: обе карманные и четыре общие", "Пять: лучшие из доступных семи"]'::jsonb,3,'f6c9fed6-f46b-5954-a02e-d37f75458597','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','ed95281f-5a39-5f27-94ca-af9314338e39','[]'::jsonb,1,true,false,true),
('На флопе все соперники сбросили карты, у одного игрока осталась живая рука. Что делать?','["Передать банк оставшемуся игроку без обязательного открытия тёрна и ривера", "Обязательно открыть тёрн и ривер, затем сравнить комбинации", "Вернуть все фишки участникам и начать раздачу заново", "Попросить оставшегося игрока обязательно доказать наличие пары"]'::jsonb,0,'624f0a4a-c0a2-5ef5-96a3-76fe261057a9','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','b6004bcc-7958-5fa6-b4a1-448e9c4a7dec','[]'::jsonb,2,true,false,true),
('За столом шесть игроков, все получили живые карты и имеют фишки. Кто первым действует на префлопе?','["Игрок на малом блайнде", "Игрок на баттоне", "Первый игрок слева от большого блайнда", "Игрок на большом блайнде"]'::jsonb,2,'f1e78686-c466-59e4-bff6-b15c2b2a03cd','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','f4cf90ec-2d9f-5639-98b7-fffb53266625','[]'::jsonb,3,true,false,true),
('SB сбросил карты на префлопе. BB остаётся в игре и имеет фишки. Кто первым действует на флопе?','["Всегда SB, даже если он уже сбросил карты", "Ближайший слева от BTN игрок с живыми картами и фишками для действия", "Первый игрок, который сделал колл на префлопе", "Всегда BTN, независимо от остальных позиций"]'::jsonb,1,'5c54fd9b-d649-5e8a-b769-291ebebe84ec','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','b6004bcc-7958-5fa6-b4a1-448e9c4a7dec','[]'::jsonb,4,true,false,true),
('На префлопе все оставшиеся игроки только уравняли полный BB. Очередь дошла до BB. Как действует дилер?','["Сразу открывает флоп: все ставки равны", "Просит BB обязательно повысить ставку", "Считает, что BB автоматически сбросил карты", "Предоставляет BB действие: чек или допустимый рейз"]'::jsonb,3,'9e4fa1b5-d8e9-550b-8232-077cc3305283','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','b6004bcc-7958-5fa6-b4a1-448e9c4a7dec','[]'::jsonb,5,true,false,true),
('В СПЛ уровень 100/200, анте 200. Сколько вносит игрок на BB при достаточном стеке и трёх или более игроках за столом?','["200 всего, включая анте", "300: 100 блайнд и 200 анте", "400: 200 BB и 200 анте", "600: 200 BB и по 200 за каждого блайнда"]'::jsonb,2,'c6773ce6-0723-5dcd-952e-313332b2e89d','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','6bf5259d-00c2-53e4-a8a6-7da665f6b583','[]'::jsonb,6,true,false,true),
('В СПЛ BB внёс 200 блайнда и 200 анте. Рейзов не было. Сколько нужно поставить для колла игроку без ранее внесённой ставки?','["200: анте не увеличивает сумму колла BB", "400: нужно покрыть весь взнос BB вместе с анте", "100: достаточно размера малого блайнда", "0: анте уже покрыло обязательную ставку"]'::jsonb,0,'5e6ff6b9-9645-5c89-b8c1-ce9abaaf06a6','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','6bf5259d-00c2-53e4-a8a6-7da665f6b583','[]'::jsonb,7,true,false,true),
('В СПЛ игроку на BB не хватает фишек на анте и блайнд. Каков порядок списания?','["Сначала BB, остаток в анте", "Сначала анте, остаток в BB", "Поровну между BB и анте", "Все фишки в BB, анте отменяется"]'::jsonb,1,'1e9b9473-16c1-5f38-99fd-4436d189ce25','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','6bf5259d-00c2-53e4-a8a6-7da665f6b583','[]'::jsonb,8,true,false,true),
('В СПЛ уровень 100/200, анте 200. На BB у игрока 250. Как распределяются его фишки?','["200 в BB и 50 в анте", "125 в BB и 125 в анте", "250 в BB, анте не берётся", "200 в анте и 50 в BB"]'::jsonb,3,'eec27ca2-be29-50fb-a54c-bda1c0544323','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','ed95281f-5a39-5f27-94ca-af9314338e39','[]'::jsonb,9,true,false,true),
('В СПЛ за столом осталось два участника. Блайнды 100/200. Какие обязательные взносы при достаточных стеках?','["SB 100, BB 200 и ещё 200 анте с BB", "SB 100 и BB 200; анте не взимается", "По 200 анте с каждого плюс блайнды", "Только BB 200; малый блайнд и анте отменяются"]'::jsonb,1,'d5cbbfa9-321d-5385-ad18-5fa6d5c51d04','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','6bf5259d-00c2-53e4-a8a6-7da665f6b583','[]'::jsonb,10,true,false,true),
('Кто первым действует на префлопе, когда за столом играют двое?','["BB, поскольку ему первой сдают карту", "Тот, кто выиграл предыдущую раздачу", "BTN/SB", "Любой участник по выбору дилера"]'::jsonb,2,'2880c5f6-63c8-530d-bb99-c34fc286b3c2','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','85bc83b1-8550-56de-90f2-38e35b3f01fc','[]'::jsonb,11,true,false,true),
('Кто первым действует на флопе в игре вдвоём, если у обоих живая рука и есть фишки?','["BB", "BTN/SB", "Последний агрессор префлопа", "Игрок с меньшим стеком"]'::jsonb,0,'1b9d5b05-d38b-572b-ab87-32e49fe26abd','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','f4cf90ec-2d9f-5639-98b7-fffb53266625','[]'::jsonb,12,true,false,true),
('За столом шесть участников, четверо сбросили карты на префлопе. Нужно ли из-за двух оставшихся рук отменить анте и переставить BTN на SB?','["Да, любая раздача с двумя руками переводит позиции в хедз-ап", "Да, но только если два игрока дошли до ривера", "Отменяется только анте, позиции не меняются", "Нет: игра двух оставшихся рук не меняет расстановку большого стола"]'::jsonb,3,'34379744-05b5-5c34-b9eb-026fefa1aedb','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','85bc83b1-8550-56de-90f2-38e35b3f01fc','[]'::jsonb,13,true,false,true),
('Сколько общих карт открывается на флопе после сжигания карты?','["Одна", "Две", "Три", "Четыре"]'::jsonb,2,'60127195-6833-5530-947d-b91d7102a7cb','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','b6004bcc-7958-5fa6-b4a1-448e9c4a7dec','[]'::jsonb,14,true,false,true),
