('Ривер — это…','["Пятая общая карта и последняя улица торгов", "Четвёртая общая карта после флопа", "Первая закрытая карта игрока", "Обязательная ставка перед каждой раздачей"]'::jsonb,0,'f5d7abdb-02e0-5d52-84e6-8cc393d8bd80','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','b6004bcc-7958-5fa6-b4a1-448e9c4a7dec','[]'::jsonb,16,true,false,true),
('На ривере все сыграли чек; олл-инов нет. Кто первым показывает руку по описанной процедуре вскрытия?','["Последний игрок, повышавший на префлопе", "Всегда игрок на BB", "Игрок с самым крупным стеком", "Ближайший слева от BTN игрок с живой рукой"]'::jsonb,3,'abb7caf8-5fb5-5848-bb14-f5fbceb5abba','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','b6004bcc-7958-5fa6-b4a1-448e9c4a7dec','[]'::jsonb,17,true,false,true),
('Один игрок уже в олл-ине, но двое других с фишками ещё могут делать ставки. Нужно ли немедленно вскрывать все руки только из-за первого олл-ина?','["Да, наличие любого олл-ина сразу завершает все торги", "Нет: обязательное вскрытие наступает, когда дальнейшие ставки всех оставшихся участников завершены", "Да, но только руку игрока с самым большим стеком", "Нет: при олл-инах карты никогда не открывают до передачи банка"]'::jsonb,1,'18c7836b-564c-5d1f-9bbf-55095b157674','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','b6004bcc-7958-5fa6-b4a1-448e9c4a7dec','[]'::jsonb,18,true,false,true),
('BTN был на месте 1, SB — 2, BB — 3; следующий игрок — на месте 4. Игрок с места 2 выбыл, осталось не менее трёх игроков. Как выглядит следующая раздача по процедуре мёртвого баттона?','["BTN на 3, SB на 4, BB на 1", "BTN на 1, SB на 3, BB на 4", "Мёртвый BTN на пустом месте 2, SB на 3, BB на 4", "BTN снова разыгрывается случайно между всеми участниками"]'::jsonb,2,'2c77ee80-eeee-5053-bce5-4b35f9ee2baf','417d5d5a-b3d3-5ad4-ab0a-d9847f59ad34','85bc83b1-8550-56de-90f2-38e35b3f01fc','[]'::jsonb,19,true,false,true),
