('Префлоп, BB 200. Игрок повышает до 600. Следующий игрок имеет право на рейз и достаточно фишек. Минимальный полный рейз — до…','["800", "1000", "1200", "1400"]'::jsonb,1,'825c9225-b3f8-5677-9568-abdffce19d71','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','dda6b8cf-902d-5f2a-835f-fd746904339d','[]'::jsonb,2,true,false,true),
('На флопе первая ставка составляет 300. При достаточном стеке минимальный полный рейз — до…','["400", "500", "600", "900"]'::jsonb,2,'847a7b31-46a1-5747-b845-9158d8634296','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','dda6b8cf-902d-5f2a-835f-fd746904339d','[]'::jsonb,3,true,false,true),
('BB текущего уровня 200. На флопе ставок ещё нет. Какова минимальная полная открывающая ставка, если это не олл-ин?','["200", "100", "150", "Размер любого одного выбранного жетона"]'::jsonb,0,'50b88ab1-d613-5ce4-b75c-52976226e0ef','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','dda6b8cf-902d-5f2a-835f-fd746904339d','[]'::jsonb,4,true,false,true),
('Что означает объявление «олл-ин»?','["Всегда полный рейз независимо от суммы", "Все оставшиеся фишки игрока; тип действия зависит от суммы и контекста", "Всегда колл, который не может превышать текущую ставку", "Выход из раздачи с возвратом прежних ставок"]'::jsonb,1,'2473f65d-445d-5859-a104-804146f47e25','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','7034af59-922c-5eeb-8bd1-e99f4cbdf84b','[]'::jsonb,5,true,false,true),
('Без анте, блайндов и иных вкладов трое игроков внесли 300, 1000 и 1000. Каковы основной банк и сайд-пот?','["Основной 300, сайд-пот 2000", "Основной 2300, сайд-пота нет", "Основной 1000, сайд-пот 1300", "Основной 900, сайд-пот 1400"]'::jsonb,3,'f7c75251-88c6-5d3d-85b1-bd9435d4ef4e','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','dda6b8cf-902d-5f2a-835f-fd746904339d','[]'::jsonb,6,true,false,true),
('В примере с вкладами 300, 1000 и 1000 игрок с вкладом 300 имеет лучшую руку. Что он может выиграть?','["Все 2300, потому что у него лучшая комбинация", "Только сайд-пот 1400", "Только основной банк 900", "Основной банк и половину сайд-пота"]'::jsonb,2,'7d0ee8c5-5468-58b7-b59b-4d789117aefc','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','dda6b8cf-902d-5f2a-835f-fd746904339d','[]'::jsonb,7,true,false,true),
('Игрок поставил 1000, единственный соперник смог уравнять лишь 600 олл-ин. Других вкладов и игроков нет. Что делать с непокрытыми 400?','["Вернуть поставившему; эти 400 не образуют разыгрываемый сайд-пот", "Включить в общий банк, на который претендует короткий стек", "Оставить в отдельном банке до следующей раздачи", "Передать в анте следующего уровня"]'::jsonb,0,'2bff07e3-56e9-5a40-b920-bc3f7aaa7961','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','dda6b8cf-902d-5f2a-835f-fd746904339d','[]'::jsonb,8,true,false,true),
('Игрок уже внёс 200 как BB и отдельно 200 анте. Затем объявил «рейз до 1000». Сколько добавить к ставке при допустимом рейзе?','["600: вычесть и BB, и анте", "1000: прежний BB не считается", "1200: анте нужно внести повторно", "800: в ставке уже есть BB 200, анте не учитывается"]'::jsonb,3,'cfb421c2-2c52-5249-91bf-b3827ad50cbe','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','7034af59-922c-5eeb-8bd1-e99f4cbdf84b','[]'::jsonb,9,true,false,true),
('Ставка перед игроком 500. Своих прежних фишек на улице нет. Он молча ставит одну фишку 1000, не объявляя рейз. Это…','["Рейз до 1000 без возможности сдачи", "Колл 500 со сдачей 500", "Олл-ин 1000 независимо от стека", "Недействительное действие: фишку нужно вернуть полностью"]'::jsonb,1,'36e01341-bd0b-5824-912c-b3f0a2091d69','a886cd1e-62ea-5c7d-9c42-6f5734e39d3e','7034af59-922c-5eeb-8bd1-e99f4cbdf84b','[]'::jsonb,10,true,false,true),
