('На флопе A первым ставит 1 000. B в очередь молча вносит 500, не в олл-ине. Как трактуется undercall?','["Всегда разрешён фолд без потери фишек", "B автоматически повышает", "Обязательное доведение до полного колла в ответ на первую ставку", "У A забирают половину ставки"]'::jsonb,2,'83128cb9-6551-5b0a-90d4-babe006e5d20','267992d6-9a38-557c-89ce-1937e0d37d74','86af4671-ea58-591f-9d98-8d630bac1ec0','[]'::jsonb,9,true,false,true),
