('В предыдущем примере A просто уравнял 200. C ранее уравнивал 125. Открыто ли C право рейза из-за суммы 200?','["Да, потому что A получил такое право", "Да, потому что есть два олл-ина", "Нет: для C прибавка только 75 при необходимом полном повышении 100", "Нет, потому что C обязан сфолдить"]'::jsonb,2,'03ced79f-2c72-5c1c-8ce5-98269e36b2a5','267992d6-9a38-557c-89ce-1937e0d37d74','0cbdc44b-130a-56c5-9d39-30bf9a6034d2','[]'::jsonb,17,true,false,true),
