('В правиле внеочередного чека формулировка «в руке остались двое» обязательно означает финальный стол из двух игроков?','["Да, иначе правило не действует", "Нет: двое могут остаться в конкретной раздаче за большим столом", "Да, но только без анте", "Да, если блайнды уже оплачены"]'::jsonb,1,'ed56f1e1-6d5f-5b98-9547-52259794e46b','267992d6-9a38-557c-89ce-1937e0d37d74','a5ee5087-1eda-5a83-96d7-87e7c525d1e4','[]'::jsonb,20,true,false,true),
('В multi-way B вне очереди повышает до 800, пропущенный A отвечает на прежнюю ставку 300 коллом. Что с действием B?','["Оно автоматически отменяется", "B может бесплатно уйти в пас", "Рейз B связывает, потому что сумма перед ним не изменилась", "Все ставки возвращаются"]'::jsonb,2,'b93ca3eb-9b4d-5f3c-86eb-4c2185d92571','267992d6-9a38-557c-89ce-1937e0d37d74','a5ee5087-1eda-5a83-96d7-87e7c525d1e4','[]'::jsonb,21,true,false,true),
