('Как дилер сообщает суммы не олл-иновых ставок?','["Дилер объявляет суммы по мере торговли", "Суммы всегда держат в секрете", "Озвучивают только победителю банка", "Дилер должен молчать при любом повышении"]'::jsonb,0,'6fca75d5-f82c-5ebf-bf87-e4d99b1db480','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','3e74ef2a-27d3-578b-b965-1fcfb3adcd64','[]'::jsonb,2,true,false,true),
