('Дилер не расслышал часть объявления. Как правильно сообщить флору?','["Прямо сказать, какую часть не слышал, не выдавая догадку за факт", "Придумать наиболее вероятные слова", "Поддержать игрока, который громче", "Утверждать, что слов не было, потому что не услышал"]'::jsonb,0,'1f1431a2-bc27-5720-baf4-a2f809bb067b','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','b5949583-835c-5bea-8cb7-a1886ade108b','[]'::jsonb,6,true,false,true),
('Что проверить после решения флора перед возобновлением игры?','["Только удовлетворены ли все игроки", "Только осталось ли время до перерыва", "Только номер стола", "Живые руки, итог действия, суммы, необходимые исправления и следующего действующего"]'::jsonb,3,'8964cfd9-7f5f-5449-8946-ef556ff087f3','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','b5949583-835c-5bea-8cb7-a1886ade108b','[]'::jsonb,7,true,false,true),
