('Нужно ли рутинно собирать ставки в центр во время продолжающихся повышений?','["Нет: это плохая практика, создающая путаницу и ошибки", "Да: после каждого отдельного колла", "Да: если дилеру так красивее", "Да: чтобы игроки не видели прежние суммы"]'::jsonb,0,'04ba6a0f-e579-58f6-ab12-c94538c46f2f','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','a2264672-4861-5e5f-966d-3ebf5c1dcfba','[]'::jsonb,10,true,false,true),
('В no-limit игрок просит точный счёт банка. Как действовать?','["Любой запрос обязывает точно посчитать", "Нужно назвать случайную оценку как точную", "Такой запрос убивает руку", "Право на точный счёт банка относится к pot-limit, в no-limit дилер его не пересчитывает"]'::jsonb,3,'3bea1076-1706-5513-9446-02b46f52c886','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','a2264672-4861-5e5f-966d-3ebf5c1dcfba','[]'::jsonb,11,true,false,true),
('Дилер раздражён долгим решением. Может ли он сам установить постоянное правило «всем по 15 секунд»?','["Да: любое раздражение разрешает clock", "Нет: применяется предусмотренная процедура clock и решение уполномоченного персонала", "Да: только лидеру турнира", "Да: если банк небольшой"]'::jsonb,1,'eda8b701-9c07-5358-9a26-82b29429fceb','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','3e74ef2a-27d3-578b-b965-1fcfb3adcd64','[]'::jsonb,12,true,false,true),
('Какова базовая длительность clock, с возможностью изменения турнирным директором?','["Всегда ровно 15 секунд", "Ровно минута без отсчёта", "До 25 секунд плюс пятисекундный обратный отсчёт", "Неограниченное время после объявления"]'::jsonb,2,'14cb4413-c134-584c-b765-c2cafe5430b6','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','591dbafb-0dcf-5f1b-ac58-c31c433a413e','[]'::jsonb,13,true,false,true),
('Перед игроком есть ставка, назначенный clock истёк, игрок не действовал. Итог?','["Рука мертва", "Автоматический колл из стека", "Автоматический рейз", "Бесплатный чек"]'::jsonb,0,'12a7690a-21fe-5b9a-ad45-d42630fb8cbe','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','591dbafb-0dcf-5f1b-ac58-c31c433a413e','[]'::jsonb,14,true,false,true),
('Перед игроком ставки нет, назначенный clock истёк. Итог?','["Рука всегда мертва", "Автоматический олл-ин", "Принудительный минимальный бет", "Чек"]'::jsonb,3,'632d2565-3790-561f-a202-8c33a06b487d','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','591dbafb-0dcf-5f1b-ac58-c31c433a413e','[]'::jsonb,15,true,false,true),
('Действие совпало с истечением clock. В чью пользу решается совпадение?','["Всегда против игрока", "В пользу игрока", "В пользу самого большого стека", "Решает зритель"]'::jsonb,1,'6f11b628-2362-5ae1-aecd-b915715f849e','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','591dbafb-0dcf-5f1b-ac58-c31c433a413e','[]'::jsonb,16,true,false,true),
('Уже сбросивший карты сообщает содержимое своей руки, пока другие ещё решают. Как реагирует дилер?','["Поощряет обсуждение", "Сам повторяет карты и советует решения", "Пресекает обсуждение и при необходимости сообщает флору", "Обязательно отменяет всю раздачу без разбора"]'::jsonb,2,'8be61f11-50c3-55f4-a0ba-b743f4bbb801','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','a24567f4-b5c6-587e-b49d-a9e5ef1a526e','[]'::jsonb,17,true,false,true),
('После корректного вскрытия зритель заметил ошибку чтения руки. Должен ли он молчать из-за принципа «один игрок — одна рука»?','["Нет: об ошибках чтения открытых рук и расчёта банка нужно сообщать", "Да: даже очевидную ошибку нельзя исправлять", "Да: говорить вправе только победитель", "Да: дилер всегда прав по определению"]'::jsonb,0,'b2e9a31f-d3fc-5644-b471-403f9a9ca3e8','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','a24567f4-b5c6-587e-b49d-a9e5ef1a526e','[]'::jsonb,18,true,false,true),
('Игрок с живой рукой использует стратегическое приложение на телефоне. Что верно?','["Это всегда разрешено, если тихо", "Это разрешено при маленьком банке", "Дилер обязан потребовать пароль от телефона", "Такая помощь и взаимодействие с устройством при живой руке запрещены; спор передают флору"]'::jsonb,3,'c936dfd8-fdfa-5dc9-b243-77e948041fcf','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','a24567f4-b5c6-587e-b49d-a9e5ef1a526e','[]'::jsonb,19,true,false,true),
('Игрок отсутствует у места к окончанию исходной сдачи последней карты всем. Как поступить с рукой?','["Ждут до его первого действия и сохраняют руку живой", "Рука гасится, смотреть карты нельзя, блайнды и анте остаются в банке", "Возвращают все обязательные ставки", "Передают карты соседу"]'::jsonb,1,'12231c9d-9395-5ed5-aab7-0152cc8bb366','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','3f780a23-65ce-59f3-9de5-42d2fe8a1f9c','[]'::jsonb,20,true,false,true),
('За столом восемь игроков, флор назначил один missed round. Сколько раздач составляет такой штраф по формуле?','["Одну", "Семь", "Восемь", "Пока баттон визуально не вернётся независимо от назначенного отсчёта"]'::jsonb,2,'20bf66e5-5756-5f76-b731-31bac3746100','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','3f780a23-65ce-59f3-9de5-42d2fe8a1f9c','[]'::jsonb,21,true,false,true),
('Игрок на штрафе пропускает раздачи. Что верно?','["Карты сдаются, обязательные ставки выставляются, рука гасится после исходной сдачи; игрок вне стола", "Он не платит блайнды и анте", "Его фишки делят между соседями", "Он играет только премиальные руки"]'::jsonb,0,'b473f362-87f7-5d1a-bec8-8fbb5dbd194b','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','3f780a23-65ce-59f3-9de5-42d2fe8a1f9c','[]'::jsonb,22,true,false,true),
('Как поступают с фишками дисквалифицированного?','["Раздают всем поровну", "Отдают победителю последней руки", "Сохраняют как общий анте-банк", "Убирают из игры"]'::jsonb,3,'3f573c4d-658a-5537-a029-b00e17662666','dc77b3ae-afdd-57c9-bad6-7ca8923cce1c','3f780a23-65ce-59f3-9de5-42d2fe8a1f9c','[]'::jsonb,23,true,false,true),
